1|// SHA-256 in plain TypeScript, so the gate (src/litmus.ts) imports nothing
2|// from node and the same module runs in the viewer's browser bundle. Output is
3|// the lowercase hex digest, identical to node's createHash('sha256') for the
4|// same UTF-8 input (tests/hash.test.ts checks it against node and against
5|// every inputHash stored in the kept result files).
6|const K = new Uint32Array([
7|  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
8|  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
9|  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
10|  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
11|  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
12|  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
13|  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
14|  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
15|]);
16|
17|const rotr = (x: number, n: number): number => (x >>> n) | (x << (32 - n));
18|
19|export function sha256Hex(input: string): string {
20|  const bytes = new TextEncoder().encode(input);
21|  const bitLength = bytes.length * 8;
22|  const paddedLength = (((bytes.length + 9 + 63) >> 6) << 6);
23|  const message = new Uint8Array(paddedLength);
24|  message.set(bytes);
25|  message[bytes.length] = 0x80;
26|  const view = new DataView(message.buffer);
27|  view.setUint32(paddedLength - 8, Math.floor(bitLength / 0x100000000));
28|  view.setUint32(paddedLength - 4, bitLength >>> 0);
29|
30|  const H = new Uint32Array([0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]);
31|  const W = new Uint32Array(64);
32|  for (let offset = 0; offset < paddedLength; offset += 64) {
33|    for (let i = 0; i < 16; i++) W[i] = view.getUint32(offset + i * 4);
34|    for (let i = 16; i < 64; i++) {
35|      const w15 = W[i - 15]!, w2 = W[i - 2]!;
36|      const s0 = rotr(w15, 7) ^ rotr(w15, 18) ^ (w15 >>> 3);
37|      const s1 = rotr(w2, 17) ^ rotr(w2, 19) ^ (w2 >>> 10);
38|      W[i] = (W[i - 16]! + s0 + W[i - 7]! + s1) >>> 0;
39|    }
40|    let a = H[0]!, b = H[1]!, c = H[2]!, d = H[3]!, e = H[4]!, f = H[5]!, g = H[6]!, h = H[7]!;
41|    for (let i = 0; i < 64; i++) {
42|      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
43|      const ch = (e & f) ^ (~e & g);
44|      const t1 = (h + S1 + ch + K[i]! + W[i]!) >>> 0;
45|      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
46|      const maj = (a & b) ^ (a & c) ^ (b & c);
47|      const t2 = (S0 + maj) >>> 0;
48|      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
49|    }
50|    H[0] = (H[0]! + a) >>> 0; H[1] = (H[1]! + b) >>> 0; H[2] = (H[2]! + c) >>> 0; H[3] = (H[3]! + d) >>> 0;
51|    H[4] = (H[4]! + e) >>> 0; H[5] = (H[5]! + f) >>> 0; H[6] = (H[6]! + g) >>> 0; H[7] = (H[7]! + h) >>> 0;
52|  }
53|  return Array.from(H, x => x.toString(16).padStart(8, '0')).join('');
54|}

