19|export function sha256Hex(input: string): string {
20|  const bytes = new TextEncoder().encode(input);
21|  const bitLength = bytes.length * 8;
22|  const paddedLength = (((bytes.length + 9 + 63) >> 6) << 6);
23|  const message = new Uint8Array(paddedLength);
24|  message.set(bytes);
25|  message[bytes.length] = 0x80;
26|  const view = new DataView(message.buffer);
27|  view.setUint32(paddedLength - 8, Math.floor(bitLength / 0x100000000));
28|  view.setUint32(paddedLength - 4, bitLength >>> 0);
29|
30|  const H = new Uint32Array([0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]);
31|  const W = new Uint32Array(64);
32|  for (let offset = 0; offset < paddedLength; offset += 64) {
33|    for (let i = 0; i < 16; i++) W[i] = view.getUint32(offset + i * 4);
34|    for (let i = 16; i < 64; i++) {
35|      const w15 = W[i - 15]!, w2 = W[i - 2]!;
36|      const s0 = rotr(w15, 7) ^ rotr(w15, 18) ^ (w15 >>> 3);
37|      const s1 = rotr(w2, 17) ^ rotr(w2, 19) ^ (w2 >>> 10);
38|      W[i] = (W[i - 16]! + s0 + W[i - 7]! + s1) >>> 0;
39|    }
40|    let a = H[0]!, b = H[1]!, c = H[2]!, d = H[3]!, e = H[4]!, f = H[5]!, g = H[6]!, h = H[7]!;
41|    for (let i = 0; i < 64; i++) {
42|      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
43|      const ch = (e & f) ^ (~e & g);
44|      const t1 = (h + S1 + ch + K[i]! + W[i]!) >>> 0;
45|      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
46|      const maj = (a & b) ^ (a & c) ^ (b & c);
47|      const t2 = (S0 + maj) >>> 0;
48|      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
49|    }
50|    H[0] = (H[0]! + a) >>> 0; H[1] = (H[1]! + b) >>> 0; H[2] = (H[2]! + c) >>> 0; H[3] = (H[3]! + d) >>> 0;
51|    H[4] = (H[4]! + e) >>> 0; H[5] = (H[5]! + f) >>> 0; H[6] = (H[6]! + g) >>> 0; H[7] = (H[7]! + h) >>> 0;
