1|// List prices per 1M tokens, USD, read from dev.meta.ai/docs/pricing-rate-limits
2|// and the Baseten and Fireworks model pages on Oct 26, 2026. Thinking tokens
3|// are already counted inside output_tokens by the Meta API, so they are not
4|// billed twice here; they are kept in usage for the results table. Meta
5|// publishes no cache-write price, so cache writes bill at the input rate and
6|// are tracked separately so the assumption is visible in every result.
7|export interface Price {
8|  input: number;
9|  cachedInput: number;
10|  cacheWrite: number;
11|  output: number;
12|}
13|
14|export const PRICES: Record<string, Price> = {
15|  'muse-spark-1.3': { input: 1.25, cachedInput: 0.15, cacheWrite: 1.25, output: 4.25 },
16|  'muse-wonder-1.0': { input: 4.0, cachedInput: 0.2, cacheWrite: 4.0, output: 20.0 },
17|  'muse-spark-open': { input: 1.25, cachedInput: 0.15, cacheWrite: 1.25, output: 4.25 },
18|};
19|
20|export interface Usage {
21|  inputTokens: number; // uncached, non-cache-write input, as the API reports it
22|  cachedInputTokens: number; // read from cache
23|  cacheWriteTokens: number; // written to cache on this call
24|  outputTokens: number; // includes thinking
25|  thinkingTokens: number;
26|}
27|
28|const USAGE_FIELDS: (keyof Usage)[] = ['inputTokens', 'cachedInputTokens', 'cacheWriteTokens', 'outputTokens', 'thinkingTokens'];
29|
30|export function costUsd(priceKey: string, usage: Usage): number {
31|  const p = PRICES[priceKey];
32|  if (!p) throw new Error(`no price on file for ${priceKey}`);
33|  for (const field of USAGE_FIELDS) {
34|    const v = usage[field];
35|    if (typeof v !== 'number' || !Number.isFinite(v)) throw new Error(`usage field ${field} is not a number`);
36|  }
37|  return (usage.inputTokens * p.input + usage.cachedInputTokens * p.cachedInput + usage.cacheWriteTokens * p.cacheWrite + usage.outputTokens * p.output) / 1_000_000;
38|}

