1|// Re-run the gate over the drafts stored in a results file. The gate is a pure
2|// function of the chart, the criteria, the denial, the case facts, and the
3|// draft (its inputHash records exactly that), so a new gate version can be
4|// applied to a kept run without a model call. Verdicts can only move in the
5|// direction the version note describes; the ledger records every re-gate.
6|//
7|//   npm run regate -- --file results/<file>.json [--file ...]
8|//
9|// Two shapes beside the appeal run (Oct 31): a dictated run was gated against
10|// the dictated copy of its case under synthetic/dictated/, which casesFor()
11|// loads when the run header says so; an intake run has no drafts, gates, or
12|// keys at all and passes through untouched. A regate that changes nothing at
13|// the current version writes nothing and records nothing.
14|import { existsSync, readFileSync, writeFileSync } from 'node:fs';
15|import { parseArgs } from 'node:util';
16|import { dirname, join } from 'node:path';
17|import { fileURLToPath } from 'node:url';
18|import { litmus, LITMUS_VERSION } from '../src/litmus.js';
19|import { classify, gateSources, loadCases, summarize, type CaseResult, type Summary } from '../src/harness.js';
20|
21|type Run = Record<string, unknown> & { litmus?: string; dictated?: { entryId: string }; regated?: { from: string; to: string; at: string; changedVerdicts: number }[] };
22|interface ResultsFile {
23|  run: Run;
24|  summary: Summary & { advice?: unknown }; // advice: the advisor's summary, written by scripts/advise.ts, never by the gate
25|  results: CaseResult[];
26|}
27|
28|// The cases a result file was gated against. A dictated run (src/dictation.ts)
29|// writes the case it built, the transcript standing in for one entry, to
30|// synthetic/dictated/<caseId>.json; those copies replace the originals here, so
31|// the gate sees the same inputs the run saw and the inputHash agrees.
32|export function casesFor(run: Run, syntheticDir: string): Map<string, ReturnType<typeof loadCases>[number]> {
33|  const byId = new Map(loadCases(join(syntheticDir, 'cases')).map(c => [c.id, c]));
34|  const dictatedDir = join(syntheticDir, 'dictated');
35|  if (run.dictated && existsSync(dictatedDir)) for (const c of loadCases(dictatedDir)) byId.set(c.id, c);
36|  return byId;
37|}
38|
39|type Gated = CaseResult & { draft: NonNullable<CaseResult['draft']>; gate: NonNullable<CaseResult['gate']> };
40|const gated = (r: CaseResult): r is Gated => Boolean(r.draft && r.gate && r.expected);
41|
42|export function regate(file: ResultsFile, casesById: Map<string, ReturnType<typeof loadCases>[number]>): { file: ResultsFile; changedVerdicts: number; changedStatuses: number; unchanged: boolean } {
43|  // Nothing in the file went through the gate (an intake run): nothing to regate.
44|  if (!file.results.some(gated)) return { file, changedVerdicts: 0, changedStatuses: 0, unchanged: true };
45|  let changedVerdicts = 0;
46|  let changedStatuses = 0;
47|  const results = file.results.map(r => {
48|    if (!gated(r)) return r;
49|    const c = casesById.get(r.caseId);
50|    if (!c) throw new Error(`case ${r.caseId} not found`);
51|    const gate = litmus(gateSources(c), r.draft);
52|    if (gate.inputHash !== r.gate.inputHash) throw new Error(`${r.caseId}: gate inputs differ from the stored run (inputHash)`);
53|    if (gate.verdict !== r.gate.verdict) changedVerdicts += 1;
54|    changedStatuses += gate.sentences.filter((s, i) => s.status !== r.gate.sentences[i]?.status).length;
55|    // The key the run was scored against is the one stored on the result: for
56|    // a payer-side run it is the inverse of the case's physician key.
57|    return { ...r, outcome: classify(r.expected.warranted, gate.verdict), gate };
58|  });
59|  const from = String(file.run.litmus ?? 'unknown');
60|  // Same version in, no label or verdict moved: the file is already what this
61|  // regate would write. Leave it, and leave run.regated[] alone.
62|  if (from === LITMUS_VERSION && changedVerdicts === 0 && changedStatuses === 0) return { file, changedVerdicts, changedStatuses, unchanged: true };
63|  const run = { ...file.run, litmus: LITMUS_VERSION, regated: [...(file.run.regated ?? []), { from, to: LITMUS_VERSION, at: new Date().toISOString(), changedVerdicts }] };
64|  // summarize() knows nothing of the advisor; keep its summary when the file has one.
65|  const summary = { ...summarize(results), ...(file.summary.advice !== undefined ? { advice: file.summary.advice } : {}) };
66|  return { file: { run, summary, results }, changedVerdicts, changedStatuses, unchanged: false };
67|}
68|
69|async function main(): Promise<void> {
70|  const { values } = parseArgs({ options: { file: { type: 'string', multiple: true } } });
71|  if (!values.file?.length) throw new Error('usage: npm run regate -- --file results/<file>.json');
72|  const here = dirname(fileURLToPath(import.meta.url));
73|  const syntheticDir = join(here, '..', 'synthetic');
74|  for (const path of values.file) {
75|    const parsed = JSON.parse(readFileSync(path, 'utf8')) as ResultsFile;
76|    const { file, changedVerdicts, changedStatuses, unchanged } = regate(parsed, casesFor(parsed.run, syntheticDir));
77|    if (unchanged) { console.log(`${path}: unchanged${parsed.run.litmus ? ` at ${String(parsed.run.litmus).split(' ')[1]}` : ' (nothing in the file went through the gate)'}; not rewritten`); continue; }
78|    writeFileSync(path, JSON.stringify(file, null, 2) + '\n');
79|    console.log(`${path}: ${changedStatuses} sentence status(es) changed, ${changedVerdicts} verdict(s) changed; now ${LITMUS_VERSION.split(' ')[1]}`);
80|  }
81|}
82|
83|if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
84|  main().catch(error => { console.error(error instanceof Error ? error.message : error); process.exit(1); });
85|}

