1|// The provider seam: one interface the harness calls, implemented for the
2|// Messages protocol (Meta Model API and Baseten, both through the Anthropic
3|// SDK with the base URL swapped) and for OpenAI-compatible endpoints
4|// (Fireworks, fallback). Everything model-specific lives here so the harness,
5|// the verifier, and the results table never see a vendor type.
6|import Anthropic from '@anthropic-ai/sdk';
7|import { APPEAL_SCHEMA, parseAppeal, type ParsedAppeal } from './schema.js';
8|import { costUsd, type Usage } from './cost.js';
9|
10|export type Effort = 'low' | 'medium' | 'high';
11|
12|export interface SystemBlock {
13|  text: string;
14|  cache?: boolean; // mark the shared prefix so it is written to and read from the prompt cache
15|}
16|
17|// The exchange so far, in the provider's own message shape, opaque to the
18|// harness: the first request, the model's turns (tool calls, redacted thinking,
19|// the draft), and the tool results. A repair turn (harness --repair) resumes it
20|// with one more user message so the model keeps its tools, its reads, and its
21|// chain of thought; the Meta docs say to replay redacted_thinking blocks.
22|export interface Transcript { readonly messages: readonly unknown[] }
23|
24|export interface Resume {
25|  transcript: Transcript;
26|  user: string; // the next user turn, e.g. the gate's reasons and the request for a revised draft
27|}
28|
29|export interface ProposeRequest {
30|  system: SystemBlock[]; // instructions (shared, cached) then the chart for this case
31|  user: string; // the denial and the payer criteria
32|  effort: Effort;
33|  maxTokens: number;
34|  resume?: Resume; // continue a prior exchange with one more user turn; `user` is the first turn and is then already in the transcript
35|}
36|
37|export interface ProposeResult {
38|  provider: string;
39|  model: string;
40|  stopReason: string | null;
41|  latencyMs: number;
42|  usage: Usage;
43|  costUsd: number;
44|  draft: ParsedAppeal;
45|  rawText: string; // kept for the verifier; the harness stores it only for synthetic runs
46|  transcript: Transcript; // the whole exchange, for a repair turn
47|}
48|
49|// --- the agentic path --------------------------------------------------------
50|// The model gets an index of the chart and tools to read entries, and the
51|// provider loops on tool_use until end_turn. Every tool call is recorded in a
52|// trace with its timestamp so a results file can replay what the model read.
53|
54|export interface ToolDefinition {
55|  name: string;
56|  description: string;
57|  inputSchema: Record<string, unknown>;
58|}
59|
60|export interface ToolCall {
61|  name: string;
62|  input: Record<string, unknown>;
63|}
64|
65|export interface ToolOutcome {
66|  ok: boolean;
67|  content: string; // what the model sees
68|  entryId?: string; // for read_entry: the entry fetched
69|  live?: boolean; // a query against an external data source, labeled as such downstream
70|  note?: string; // short human-readable note for the trace
71|}
72|
73|export interface TraceEvent {
74|  step: number;
75|  tool: string;
76|  input: Record<string, unknown>;
77|  entryId?: string;
78|  atMs: number; // since the case started
79|  ok: boolean;
80|  live?: boolean;
81|  note?: string;
82|  why?: string; // the model's one-sentence reason for the call, from the tool input's `why` field (the API returns only redacted thinking), at most 400 characters
83|  repair?: number; // set by the harness: the repair turn this call was made in; absent for the first turn
84|}
85|
86|export interface AgenticRequest extends ProposeRequest {
87|  tools: ToolDefinition[];
88|  execute: (call: ToolCall) => Promise<ToolOutcome>;
89|  maxTurns?: number; // model turns, each ending in tool_use or end_turn; default 24
90|}
91|
92|export interface AgenticResult extends ProposeResult {
93|  turns: number;
94|  trace: TraceEvent[];
95|}
96|
97|// A plain structured question, used by the advisor: system, user, a JSON
98|// schema for the answer, and the text back. No tools, no appeal contract.
99|export interface AskRequest {
100|  system: SystemBlock[];
101|  user: string;
102|  schema: Record<string, unknown>;
103|  effort: Effort;
104|  maxTokens: number;
105|}
106|
107|export interface AskResult {
108|  provider: string;
109|  model: string;
110|  stopReason: string | null;
111|  latencyMs: number;
112|  usage: Usage;
113|  costUsd: number;
114|  rawText: string;
115|}
116|
117|export interface Provider {
118|  readonly label: string;
119|  readonly model: string;
120|  propose(request: ProposeRequest): Promise<ProposeResult>;
121|  proposeAgentic?(request: AgenticRequest): Promise<AgenticResult>;
122|  ask?(request: AskRequest): Promise<AskResult>;
123|}
124|
125|// Fields the Meta Model API answers with HTTP 400 (dev.meta.ai/docs/protocols/messages,
126|// Oct 26, 2026). The provider never sets them; the test pins that.
127|export const FORBIDDEN_FIELDS = ['stop_sequences', 'top_k', 'container', 'inference_geo', 'tool_choice', 'thinking'] as const;
128|
129|interface MetaUsage {
130|  input_tokens?: unknown;
131|  output_tokens?: unknown;
132|  cache_read_input_tokens?: unknown;
133|  cache_creation_input_tokens?: unknown;
134|  output_tokens_details?: { thinking_tokens?: unknown } | null;
135|}
136|
137|function count(value: unknown, field: string, optional = false): number {
138|  if (value === undefined || value === null) {
139|    if (optional) return 0;
140|    throw new Error(`usage field ${field} missing from the response`);
141|  }
142|  if (typeof value !== 'number' || !Number.isFinite(value)) throw new Error(`usage field ${field} is not a number`);
143|  return value;
144|}
145|
146|export interface MessagesProviderOptions {
147|  label: string;
148|  baseURL: string;
149|  authToken: string;
150|  model: string;
151|  priceKey?: string; // defaults to model
152|  fetch?: typeof fetch; // tests inject a fake
153|}
154|
155|export function messagesProvider(options: MessagesProviderOptions): Provider {
156|  const client = new Anthropic({
157|    baseURL: options.baseURL,
158|    authToken: options.authToken,
159|    apiKey: null,
160|    maxRetries: 2,
161|    timeout: 180_000,
162|    ...(options.fetch ? { fetch: options.fetch } : {}),
163|  });
164|  const priceKey = options.priceKey ?? options.model;
165|
166|  const readUsage = (response: Anthropic.Message): Usage => {
167|    const u = (response.usage ?? {}) as MetaUsage;
168|    return {
169|      inputTokens: count(u.input_tokens, 'input_tokens'),
170|      cachedInputTokens: count(u.cache_read_input_tokens, 'cache_read_input_tokens', true),
171|      cacheWriteTokens: count(u.cache_creation_input_tokens, 'cache_creation_input_tokens', true),
172|      outputTokens: count(u.output_tokens, 'output_tokens'),
173|      thinkingTokens: count(u.output_tokens_details?.thinking_tokens, 'thinking_tokens', true),
174|    };
175|  };
176|  const systemBlocks = (request: ProposeRequest) => request.system.map(b => ({ type: 'text' as const, text: b.text, ...(b.cache ? { cache_control: { type: 'ephemeral' as const } } : {}) }));
177|  const textOf = (response: Anthropic.Message) => response.content.filter((b): b is Anthropic.TextBlock => b.type === 'text').map(b => b.text).join('');
178|
179|  return {
180|    label: options.label,
181|    model: options.model,
182|
183|    async proposeAgentic(request: AgenticRequest): Promise<AgenticResult> {
184|      const started = Date.now();
185|      const maxTurns = request.maxTurns ?? 24;
186|      const messages: Anthropic.MessageParam[] = request.resume
187|        ? [...(request.resume.transcript.messages as Anthropic.MessageParam[]), { role: 'user', content: request.resume.user }]
188|        : [{ role: 'user', content: request.user }];
189|      const trace: TraceEvent[] = [];
190|      const usage: Usage = { inputTokens: 0, cachedInputTokens: 0, cacheWriteTokens: 0, outputTokens: 0, thinkingTokens: 0 };
191|      let turns = 0;
192|      let response: Anthropic.Message | null = null;
193|      while (turns < maxTurns) {
194|        // tool_choice stays at its default (auto): the Meta endpoint rejects a named tool.
195|        response = await client.messages.create({
196|          model: options.model,
197|          max_tokens: request.maxTokens,
198|          system: systemBlocks(request),
199|          tools: request.tools.map(t => ({ name: t.name, description: t.description, input_schema: t.inputSchema as Anthropic.Tool['input_schema'] })),
200|          output_config: { effort: request.effort, format: { type: 'json_schema', schema: APPEAL_SCHEMA } },
201|          messages,
202|        });
203|        turns += 1;
204|        const u = readUsage(response);
205|        usage.inputTokens += u.inputTokens;
206|        usage.cachedInputTokens += u.cachedInputTokens;
207|        usage.cacheWriteTokens += u.cacheWriteTokens;
208|        usage.outputTokens += u.outputTokens;
209|        usage.thinkingTokens += u.thinkingTokens;
210|        const toolUses = response.content.filter((b): b is Anthropic.ToolUseBlock => b.type === 'tool_use');
211|        if (response.stop_reason !== 'tool_use' || toolUses.length === 0) break;
212|        const results: Anthropic.ToolResultBlockParam[] = [];
213|        for (const call of toolUses) {
214|          const input = (call.input ?? {}) as Record<string, unknown>;
215|          const atMs = Date.now() - started;
216|          let outcome: ToolOutcome;
217|          try {
218|            outcome = await request.execute({ name: call.name, input });
219|          } catch (error: unknown) {
220|            outcome = { ok: false, content: `tool failed: ${error instanceof Error ? error.constructor.name : 'Error'}`, note: 'tool threw' };
221|          }
222|          const why = typeof input['why'] === 'string' ? input['why'].trim().slice(0, 400) : '';
223|          trace.push({
224|            step: trace.length, tool: call.name, input, atMs, ok: outcome.ok,
225|            ...(outcome.entryId ? { entryId: outcome.entryId } : {}),
226|            ...(outcome.live ? { live: true } : {}),
227|            ...(outcome.note ? { note: outcome.note } : {}),
228|            ...(why ? { why } : {}),
229|          });
230|          results.push({ type: 'tool_result', tool_use_id: call.id, content: outcome.content, ...(outcome.ok ? {} : { is_error: true }) });
231|        }
232|        messages.push({ role: 'assistant', content: response.content as Anthropic.ContentBlockParam[] });
233|        messages.push({ role: 'user', content: results });
234|      }
235|      const latencyMs = Date.now() - started;
236|      const ended = response !== null && response.stop_reason !== 'tool_use';
237|      const rawText = response && ended ? textOf(response) : '';
238|      const stopReason = ended ? response!.stop_reason : 'max_turns';
239|      // The final assistant turn joins the transcript so a repair turn can follow it.
240|      if (response && ended) messages.push({ role: 'assistant', content: response.content as Anthropic.ContentBlockParam[] });
241|      return {
242|        provider: options.label,
243|        model: response?.model ?? options.model,
244|        stopReason,
245|        latencyMs,
246|        usage,
247|        costUsd: costUsd(priceKey, usage),
248|        draft: rawText ? parseAppeal(rawText) : { ok: false, error: `no text in response (stop reason ${stopReason})` },
249|        rawText,
250|        transcript: { messages },
251|        turns,
252|        trace,
253|      };
254|    },
255|
256|    async ask(request: AskRequest): Promise<AskResult> {
257|      const started = Date.now();
258|      const response = await client.messages.create({
259|        model: options.model,
260|        max_tokens: request.maxTokens,
261|        system: systemBlocks(request),
262|        output_config: { effort: request.effort, format: { type: 'json_schema', schema: request.schema } },
263|        messages: [{ role: 'user', content: request.user }],
264|      });
265|      const latencyMs = Date.now() - started;
266|      const usage = readUsage(response);
267|      return { provider: options.label, model: response.model, stopReason: response.stop_reason, latencyMs, usage, costUsd: costUsd(priceKey, usage), rawText: textOf(response) };
268|    },
269|
270|    async propose(request: ProposeRequest): Promise<ProposeResult> {
271|      const started = Date.now();
272|      const messages: Anthropic.MessageParam[] = request.resume
273|        ? [...(request.resume.transcript.messages as Anthropic.MessageParam[]), { role: 'user', content: request.resume.user }]
274|        : [{ role: 'user', content: request.user }];
275|      const response = await client.messages.create({
276|        model: options.model,
277|        max_tokens: request.maxTokens,
278|        system: systemBlocks(request),
279|        output_config: { effort: request.effort, format: { type: 'json_schema', schema: APPEAL_SCHEMA } },
280|        messages,
281|      });
282|      const latencyMs = Date.now() - started;
283|      const usage = readUsage(response);
284|      const rawText = textOf(response);
285|      messages.push({ role: 'assistant', content: response.content as Anthropic.ContentBlockParam[] });
286|      return {
287|        provider: options.label,
288|        model: response.model,
289|        stopReason: response.stop_reason,
290|        latencyMs,
291|        usage,
292|        costUsd: costUsd(priceKey, usage),
293|        draft: rawText ? parseAppeal(rawText) : { ok: false, error: `no text in response (stop reason ${response.stop_reason})` },
294|        rawText,
295|        transcript: { messages },
296|      };
297|    },
298|  };
299|}
300|
301|export interface OpenAiProviderOptions {
302|  label: string;
303|  baseURL: string; // e.g. https://api.fireworks.ai/inference/v1
304|  apiKey: string;
305|  model: string;
306|  priceKey: string;
307|  fetch?: typeof fetch;
308|}
309|
310|interface ChatCompletion {
311|  model: string;
312|  choices: { message: { content: string | null }; finish_reason: string | null }[];
313|  usage?: {
314|    prompt_tokens?: unknown;
315|    completion_tokens?: unknown;
316|    prompt_tokens_details?: { cached_tokens?: unknown } | null;
317|    completion_tokens_details?: { reasoning_tokens?: unknown } | null;
318|  } | null;
319|}
320|
321|// Fallback path for OpenAI-compatible hosts. Kept to fetch so the only SDK in
322|// the harness is the one the primary path needs.
323|export function openAiProvider(options: OpenAiProviderOptions): Provider {
324|  const doFetch = options.fetch ?? fetch;
325|  return {
326|    label: options.label,
327|    model: options.model,
328|    async propose(request: ProposeRequest): Promise<ProposeResult> {
329|      const started = Date.now();
330|      const turns: { role: string; content: string }[] = request.resume
331|        ? [...(request.resume.transcript.messages as { role: string; content: string }[]), { role: 'user', content: request.resume.user }]
332|        : [{ role: 'user', content: request.user }];
333|      const res = await doFetch(`${options.baseURL.replace(/\/$/, '')}/chat/completions`, {
334|        method: 'POST',
335|        headers: { 'content-type': 'application/json', authorization: `Bearer ${options.apiKey}` },
336|        body: JSON.stringify({
337|          model: options.model,
338|          max_tokens: request.maxTokens,
339|          reasoning_effort: request.effort,
340|          response_format: { type: 'json_schema', json_schema: { name: 'appeal', schema: APPEAL_SCHEMA, strict: true } },
341|          messages: [
342|            { role: 'system', content: request.system.map(b => b.text).join('\n\n') },
343|            ...turns,
344|          ],
345|        }),
346|      });
347|      const latencyMs = Date.now() - started;
348|      if (!res.ok) throw new Error(`${options.label} returned HTTP ${res.status}`);
349|      const body = (await res.json()) as ChatCompletion;
350|      if (!body.usage) throw new Error(`${options.label} response has no usage block`);
351|      const choice = body.choices[0];
352|      const rawText = choice?.message.content ?? '';
353|      const cached = count(body.usage.prompt_tokens_details?.cached_tokens, 'cached_tokens', true);
354|      const usage: Usage = {
355|        inputTokens: count(body.usage.prompt_tokens, 'prompt_tokens') - cached,
356|        cachedInputTokens: cached,
357|        cacheWriteTokens: 0,
358|        outputTokens: count(body.usage.completion_tokens, 'completion_tokens'),
359|        thinkingTokens: count(body.usage.completion_tokens_details?.reasoning_tokens, 'reasoning_tokens', true),
360|      };
361|      return {
362|        provider: options.label,
363|        model: body.model,
364|        stopReason: choice?.finish_reason ?? null,
365|        latencyMs,
366|        usage,
367|        costUsd: costUsd(options.priceKey, usage),
368|        draft: rawText ? parseAppeal(rawText) : { ok: false, error: 'no text in response' },
369|        rawText,
370|        transcript: { messages: [...turns, { role: 'assistant', content: rawText }] },
371|      };
372|    },
