118|export function chartToolExecutor(c: SyntheticCase, extra?: (call: ToolCall) => Promise<ToolOutcome | null>): (call: ToolCall) => Promise<ToolOutcome> {
119|  return async call => {
120|    if (call.name === 'list_entries') return { ok: true, content: chartIndex(c), note: `${c.chart.length} entries` };
121|    if (call.name === 'read_entry') {
122|      const id = String(call.input['id'] ?? '').trim();
123|      const e = c.chart.find(x => x.id === id);
124|      if (!e) return { ok: false, content: `no such entry: ${id.slice(0, 40) || '(empty)'}. Ids look like note-012; call list_entries to see them.`, entryId: id, note: 'no such entry' };
125|      return { ok: true, content: `[${e.id}] ${e.date} ${e.kind}\n${e.text}`, entryId: e.id };
126|    }
127|    const handled = extra ? await extra(call) : null;
128|    if (handled) return handled;
129|    return { ok: false, content: `unknown tool: ${call.name}`, note: 'unknown tool' };
130|  };
