406|    cost += r.costUsd;
407|    latency += r.latencyMs;
408|    stopReason = r.stopReason;
409|    transcript = r.transcript;
410|    const record: RepairRecord = { turn, reasons, sent: text, stopReason: r.stopReason, latencyMs: r.latencyMs, usage: r.usage, costUsd: r.costUsd, toolCalls: repairTrace.length };
411|    if (!r.draft.ok) {
412|      repairs.push({ ...record, error: `parse failed: ${r.draft.error}` });
413|      if (opts.verbose) log(`repair turn ${turn} failed: ${r.draft.error}`);
414|      break;
415|    }
416|    appeal = r.draft.appeal;
417|    gate = litmus(sources, appeal);
418|    repairs.push({ ...record, draft: appeal, gate, outcome: classify(expected.warranted, gate.verdict) });
419|  }
420|
421|  const outcome = classify(expected.warranted, gate.verdict);
422|  if (opts.verbose) for (const line of verboseVerdict(gate, sources)) log(line);
423|  const verifiedEvidence = gate.evidence.filter(e => e.status === 'verified');
424|  const onKey = verifiedEvidence.filter(e => (c.expected.support[e.criterion] ?? []).includes(e.citation)).length;
425|  return {
426|    ...base, stopReason, latencyMs: latency, usage, costUsd: cost,
427|    ...(agentic ? withReading(trace, turns) : {}),
428|    outcome,
429|    warrantedMatch: appeal.warranted === expected.warranted,
430|    citationPrecision: verifiedEvidence.length > 0 ? onKey / verifiedEvidence.length : null,
431|    draft: appeal,
432|    gate,
433|    ...(budget > 0 ? { firstOutcome, repairs, ...(repairs.some(x => x.gate) ? { firstGate } : {}) } : {}),
434|  };
435|}
