79|// service; the denial is warranted exactly where it does not.
80|export function expectedFor(c: SyntheticCase, side: Side = 'physician'): { warranted: boolean; subtype?: string } {
81|  const warranted = side === 'payer' ? !c.expected.warranted : c.expected.warranted;
82|  return { warranted, ...(c.expected.subtype ? { subtype: c.expected.subtype } : {}) };
