118|export function chartToolExecutor(c: SyntheticCase, extra?: (call: ToolCall) => Promise<ToolOutcome | null>): (call: ToolCall) => Promise<ToolOutcome> {
119|  return async call => {
120|    if (call.name === 'list_entries') return { ok: true, content: chartIndex(c), note: `${c.chart.length} entries` };
121|    if (call.name === 'read_entry') {
122|      const id = String(call.input['id'] ?? '').trim();
