242|// The repair turn's text. The gate's record goes back verbatim: for every
243|// unverified sentence its index, status, reason, and the alsoCite entries of a
244|// needs-citation; then the draft-level reasons (an empty warranted draft, a
245|// criterion with no verified evidence). The model is asked for the complete
246|// revised draft under the same schema, and told that declining is an answer.
247|export function repairMessage(gate: GateResult): { text: string; reasons: string[] } {
248|  const reasons: string[] = [];
249|  for (const s of gate.sentences) {
250|    if (s.status === 'verified') continue;
251|    reasons.push(`sentence ${s.index} ${s.status}: ${s.reason}${s.alsoCite && s.alsoCite.length > 0 ? ` [alsoCite: ${s.alsoCite.join(', ')}]` : ''}`);
252|  }
253|  for (const r of gate.reasons) if (!/^sentence \d+ /.test(r)) reasons.push(r);
254|  const text = [
255|    'The verifier blocked this draft. Its record, verbatim, one line per finding:',
256|    ...reasons.map(r => `- ${r}`),
257|    '',
258|    'Return the complete revised draft as the same JSON object: warranted, reason, every evidence item, and every sentence, each with one citation and a quote copied exactly from that entry. Keep every sentence that verified. A sentence returned as needs-citation states a fact that lives in a different entry: read that entry and cite it for the fact, or rewrite the sentence without the fact. A refuted token appears in no admissible source: remove it or replace it with what the cited entry says. A criterion with no verified evidence needs an evidence item quoting an entry that supports it. If, on reading again, the record does not support the appeal, set warranted to false with your reason and leave sentences empty.',
259|  ].join('\n');
260|  return { text, reasons };
261|}
