263|// One tool call as a line for a 140-column terminal (harness --verbose): time
264|// since the case started, the tool, its input, the entry id, ok or failed, and
265|// the model's why. Wide fields are cut so the line never wraps.
266|export function verboseLine(t: TraceEvent): string {
267|  const secs = `${(t.atMs / 1000).toFixed(1)} s`.padStart(8);
268|  const tool = t.tool.padEnd(14);
269|  const input = t.tool === 'read_entry'
270|    ? String(t.input['id'] ?? t.entryId ?? '')
271|    : Object.entries(t.input).filter(([k]) => k !== 'why').map(([, v]) => String(v)).join(' ');
272|  const target = (t.entryId && t.tool !== 'read_entry' ? `${input} ${t.entryId}` : input).slice(0, 36).padEnd(36);
273|  const ok = (t.ok ? 'ok' : 'failed').padEnd(7);
274|  const live = t.live ? 'live ' : '';
275|  const head = `${secs}  ${tool} ${target} ${ok} ${live}`;
276|  const room = 140 - head.length;
277|  const why = t.why ? `why: ${t.why}` : t.note ? t.note : '';
278|  const tail = why.length > room ? `${why.slice(0, Math.max(0, room - 1))}…` : why;
279|  return `${head}${tail}`.trimEnd();
280|}
281|
282|// The verdict block that ends a verbose run: verdict and counts, gate version,
283|// the gate's input hash (sources and draft), and the sources hash (the record
284|// alone, shared with the kept replay of the same case in the viewer).
285|export function verboseVerdict(gate: GateResult, sources: ReturnType<typeof gateSources>): string[] {
286|  const version = /v\d+(?:\.\d+)?/.exec(gate.litmus)?.[0] ?? gate.litmus.slice(0, 20);
287|  const name = gate.verdict.toUpperCase();
288|  const counts = `${gate.counts.verified} of ${gate.counts.sentences} sentences verified`;
289|  const lines = [`verdict ${name}  ${counts}  gate ${version}`];
290|  if (gate.verdict === 'declined' && gate.declinedReason) lines.push(`reason  ${gate.declinedReason}`.slice(0, 140));
291|  for (const r of gate.reasons) lines.push(`reason  ${r}`.slice(0, 140));
292|  lines.push(`input hash    ${gate.inputHash}`);
293|  lines.push(`sources hash  ${sourcesHash(sources)}`);
294|  return lines;
295|}
