316|export async function runCase(provider: Provider, c: SyntheticCase, opts: RunOptions): Promise<CaseResult> {
317|  const side: Side = opts.side ?? 'physician';
318|  const expected = expectedFor(c, side);
319|  const budget = Math.max(0, Math.floor(opts.repair ?? 0));
320|  const log = opts.log ?? ((line: string) => console.error(line));
321|  const base = {
322|    caseId: c.id, category: c.category, setting: c.setting, stakesUsd: c.stakesUsd,
323|    expected,
324|    ...(side === 'payer' ? { side } : {}),
325|    provider: provider.label, model: provider.model,
326|  };
327|  const started = Date.now();
328|  // Verbose: every tool call is printed as it happens, from the executor the
329|  // provider calls, so the line appears before the model's next turn.
330|  const extra = opts.extra;
331|  const verboseExtra = opts.verbose
332|    ? async (call: ToolCall): Promise<ToolOutcome | null> => {
333|        const out = extra ? await extra(call) : null;
334|        if (out) log(verboseLine({ step: 0, tool: call.name, input: call.input, atMs: Date.now() - started, ok: out.ok, ...(out.entryId ? { entryId: out.entryId } : {}), ...(out.live ? { live: true } : {}), ...(out.note ? { note: out.note } : {}), ...(typeof call.input['why'] === 'string' ? { why: String(call.input['why']).trim().slice(0, 400) } : {}) }));
335|        return out;
336|      }
337|    : extra;
338|  const verboseExecute = (execute: (call: ToolCall) => Promise<ToolOutcome>) => async (call: ToolCall): Promise<ToolOutcome> => {
339|    const out = await execute(call);
340|    if (opts.verbose && call.name !== POLICY_STATUS_TOOL.name) log(verboseLine({ step: 0, tool: call.name, input: call.input, atMs: Date.now() - started, ok: out.ok, ...(out.entryId ? { entryId: out.entryId } : {}), ...(out.note ? { note: out.note } : {}), ...(typeof call.input['why'] === 'string' ? { why: String(call.input['why']).trim().slice(0, 400) } : {}) }));
341|    return out;
342|  };
343|  const agenticRequest = (resume?: Resume): AgenticRequest => {
344|    const req = buildAgenticRequest(c, opts.effort, opts.maxTokens, { ...(opts.tools ? { tools: opts.tools } : {}), ...(verboseExtra ? { extra: verboseExtra } : {}), side });
345|    return { ...req, execute: verboseExecute(req.execute), ...(resume ? { resume } : {}) };
346|  };
347|  const plainRequest = (resume?: Resume): ProposeRequest => ({ ...buildRequest(c, opts.effort, opts.maxTokens, side), ...(resume ? { resume } : {}) });
348|
349|  let result;
350|  let agentic: { turns: number; trace: TraceEvent[] } | null = null;
351|  try {
352|    if (opts.agentic) {
353|      if (!provider.proposeAgentic) throw new Error(`${provider.label} has no agentic path`);
354|      const r = await provider.proposeAgentic(agenticRequest());
355|      result = r;
356|      agentic = { turns: r.turns, trace: r.trace };
357|    } else {
358|      result = await provider.propose(plainRequest());
359|    }
360|  } catch (error: unknown) {
361|    // Error class and HTTP status only: SDK messages can echo the request body.
362|    const status = (error as { status?: number }).status;
363|    const kind = error instanceof Error ? error.constructor.name : 'Error';
364|    return { ...base, stopReason: null, latencyMs: 0, usage: EMPTY_USAGE, costUsd: 0, outcome: 'error', warrantedMatch: null, citationPrecision: null, error: `request failed: ${kind}${status ? ` (HTTP ${status})` : ''}` };
365|  }
366|  const sources = gateSources(c);
367|  const withReading = (trace: TraceEvent[], turns: number) => ({ turns, trace, reading: readingStats(c, trace) });
368|  if (!result.draft.ok) {
369|    const common = { ...base, stopReason: result.stopReason, latencyMs: result.latencyMs, usage: result.usage, costUsd: result.costUsd, ...(agentic ? withReading(agentic.trace, agentic.turns) : {}) };
370|    if (opts.verbose) log(`answer failed: ${result.draft.error}`);
371|    return { ...common, outcome: 'error', warrantedMatch: null, citationPrecision: null, error: `parse failed: ${result.draft.error}`, rawPreview: result.rawText.slice(0, 400) };
372|  }
373|
374|  let appeal = result.draft.appeal;
375|  let gate = litmus(sources, appeal);
376|  const firstGate = gate;
377|  const firstOutcome = classify(expected.warranted, gate.verdict);
378|  let usage = result.usage;
379|  let cost = result.costUsd;
380|  let latency = result.latencyMs;
381|  let stopReason = result.stopReason;
382|  let transcript = result.transcript;
383|  const trace: TraceEvent[] = agentic ? agentic.trace.slice() : [];
384|  let turns = agentic?.turns ?? 0;
385|  const repairs: RepairRecord[] = [];
386|
387|  // The repair turn: only a blocked draft is offered one, never a declined
388|  // draft (the model's decision to decline stands) and never a passing one.
389|  for (let turn = 1; turn <= budget && gate.verdict === 'blocked'; turn++) {
390|    const { text, reasons } = repairMessage(gate);
391|    if (opts.verbose) { log(`repair turn ${turn}: the gate's record sent back, ${reasons.length} line(s)`); for (const r of reasons) log(`  ${r}`.slice(0, 140)); }
392|    let r: ProposeResult | AgenticResult;
393|    try {
394|      r = opts.agentic ? await provider.proposeAgentic!(agenticRequest({ transcript, user: text })) : await provider.propose(plainRequest({ transcript, user: text }));
395|    } catch (error: unknown) {
396|      const status = (error as { status?: number }).status;
397|      const kind = error instanceof Error ? error.constructor.name : 'Error';
398|      repairs.push({ turn, reasons, sent: text, stopReason: null, latencyMs: 0, usage: EMPTY_USAGE, costUsd: 0, toolCalls: 0, error: `request failed: ${kind}${status ? ` (HTTP ${status})` : ''}` });
399|      break;
400|    }
401|    const ag = r as Partial<AgenticResult>;
402|    const repairTrace: TraceEvent[] = ag.trace ?? [];
403|    for (const e of repairTrace) trace.push({ ...e, step: trace.length, atMs: latency + e.atMs, repair: turn });
404|    turns += ag.turns ?? 0;
405|    usage = addUsage(usage, r.usage);
406|    cost += r.costUsd;
407|    latency += r.latencyMs;
408|    stopReason = r.stopReason;
409|    transcript = r.transcript;
410|    const record: RepairRecord = { turn, reasons, sent: text, stopReason: r.stopReason, latencyMs: r.latencyMs, usage: r.usage, costUsd: r.costUsd, toolCalls: repairTrace.length };
411|    if (!r.draft.ok) {
412|      repairs.push({ ...record, error: `parse failed: ${r.draft.error}` });
413|      if (opts.verbose) log(`repair turn ${turn} failed: ${r.draft.error}`);
414|      break;
415|    }
416|    appeal = r.draft.appeal;
417|    gate = litmus(sources, appeal);
418|    repairs.push({ ...record, draft: appeal, gate, outcome: classify(expected.warranted, gate.verdict) });
419|  }
420|
421|  const outcome = classify(expected.warranted, gate.verdict);
422|  if (opts.verbose) for (const line of verboseVerdict(gate, sources)) log(line);
423|  const verifiedEvidence = gate.evidence.filter(e => e.status === 'verified');
424|  const onKey = verifiedEvidence.filter(e => (c.expected.support[e.criterion] ?? []).includes(e.citation)).length;
425|  return {
426|    ...base, stopReason, latencyMs: latency, usage, costUsd: cost,
427|    ...(agentic ? withReading(trace, turns) : {}),
428|    outcome,
429|    warrantedMatch: appeal.warranted === expected.warranted,
430|    citationPrecision: verifiedEvidence.length > 0 ? onKey / verifiedEvidence.length : null,
431|    draft: appeal,
432|    gate,
433|    ...(budget > 0 ? { firstOutcome, repairs, ...(repairs.some(x => x.gate) ? { firstGate } : {}) } : {}),
434|  };
435|}
