666|  mkdirSync(outDir, { recursive: true });
667|  const file = join(outDir, resultFileName({ label: values.label ?? provider.label, model: provider.model, effort, agentic, chart, startedAt, side, repair }));
668|  writeFileSync(file, JSON.stringify({ run: { startedAt, finishedAt: new Date().toISOString(), provider: provider.label, model: provider.model, effort, concurrency, maxTokens, cases: cases.length, agentic, side, ...(repair ? { repair } : {}), tools: ['list_entries', 'read_entry', ...tools.map(t => t.name)], litmus: LITMUS_VERSION, synthetic: true }, summary, results }, null, 2) + '\n');
