1|// The instrument. A passing draft rendered as the document the physician would
2|// sign: the payer's own reason quoted at the head, each sentence with a
3|// footnote carrying the cited entry, its date, its kind, and the verified
4|// quote, the gate's version and input hash at the foot, and a blank signature
5|// line under a band that says what this is: a draft, unsigned, not sent. Pure
6|// functions over the case and the stored result; nothing here calls a model
7|// and nothing is saved.
8|import { payerRemark, type RecordStatus, type ResultsFile, type ViewerCase, type ViewerResult } from './replay.js';
9|
10|export interface WritFootnote { n: number; entryId: string; date: string; kind: string; quote: string }
11|
12|export interface WritDocument {
13|  heading: string;
14|  to: string;
15|  re: string;
16|  payerReason: string | null;
17|  opening: string;
18|  sentences: { n: number; text: string }[];
19|  footnotes: WritFootnote[];
20|  provenance: string;
21|  signature: string;
22|  band: string;
23|}
24|
25|export const WRIT_BUTTON = 'the writ';
26|export const WRIT_HELP = 'The passing draft as the instrument the physician would sign: every sentence footnoted to the chart entry it cites, the gate’s version and input hash at the foot, and a blank signature line. A draft, unsigned, not sent. Print it or save it as text; nothing here is sent anywhere.';
27|export const WRIT_BAND = 'DRAFT, unsigned, not sent. Prepared by a machine and verified against the record by the gate; it becomes an appeal only under the physician’s signature, and the physician decides whether the record satisfies the criteria.';
28|export const WRIT_SIGNATURE = 'Reviewed and signed: ____________________________, MD        Date: ______________';
29|export const WRIT_OPENING = 'The payer’s stated reason is quoted above. The record, cited entry by entry below, documents the following.';
30|
31|export function writDocument(c: ViewerCase, r: ViewerResult, run: ResultsFile['run']): WritDocument | null {
32|  const gate = r.gate;
33|  if (!gate || gate.verdict !== 'pass' || gate.sentences.length === 0) return null;
34|  if (!gate.sentences.every(s => s.status === 'verified')) return null;
35|  const entries = new Map(c.chart.map(e => [e.id, e]));
36|  const sentences = gate.sentences.map((s, i) => ({ n: i + 1, text: s.text }));
37|  const footnotes: WritFootnote[] = gate.sentences.map((s, i) => {
38|    const e = entries.get(s.citation);
39|    return { n: i + 1, entryId: s.citation, date: e?.date ?? '', kind: e?.kind ?? '', quote: s.quote };
40|  });
41|  const service = `${c.procedure.codeSystem} ${c.procedure.code}, ${c.procedure.description}`;
42|  const dates = c.denial.serviceEnd ? `${c.denial.dateOfService} to ${c.denial.serviceEnd}` : c.denial.dateOfService;
43|  const hash = (gate as { inputHash?: string }).inputHash;
44|  const version = /v\d+(?:\.\d+)?/.exec(gate.litmus ?? '')?.[0] ?? '';
45|  const repaired = run.repair && r.repairs && r.repairs.length > 0 ? ` after ${r.repairs.length} repair turn${r.repairs.length > 1 ? 's' : ''} (post hoc; the first verdict was blocked)` : '';
46|  const provenance = `Drafted by ${run.model} (${run.provider}), run started ${run.startedAt.slice(0, 10)}, from the synthetic record of ${c.patient.alias}${repaired}. Every sentence verified against its cited entry by the LITMUS gate ${version}${hash ? `; input hash ${hash}` : ''}. Synthetic data only.`;
47|  return {
48|    heading: 'Response to claim denial',
49|    to: `${c.payer.name}, ${c.payer.planType}`,
50|    re: `${service}; date of service ${dates}; denied under CARC ${c.denial.carc}${c.denial.rarc ? `, RARC ${c.denial.rarc}` : ''}; ${c.patient.alias}, ${c.patient.age} year old ${c.patient.sex}`,
51|    payerReason: payerRemark(c),
52|    opening: WRIT_OPENING,
53|    sentences,
54|    footnotes,
55|    provenance,
56|    signature: WRIT_SIGNATURE,
57|    band: WRIT_BAND,
58|  };
59|}
60|
61|export function writText(doc: WritDocument): string {
62|  const lines: string[] = [];
63|  lines.push(doc.band, '');
64|  lines.push(doc.heading.toUpperCase(), '');
65|  lines.push(`To: ${doc.to}`);
66|  lines.push(`Re: ${doc.re}`, '');
67|  if (doc.payerReason) lines.push(`The payer’s reason: “${doc.payerReason}”`, '');
68|  lines.push(doc.opening, '');
69|  lines.push(doc.sentences.map(s => `${s.text} [${s.n}]`).join(' '), '');
70|  lines.push('Record cited');
71|  for (const f of doc.footnotes) lines.push(`[${f.n}] ${f.entryId}, ${f.date}, ${f.kind}: “${f.quote}”`);
72|  lines.push('', doc.provenance, '', doc.signature, '');
73|  return lines.join('\n');
