76|// The footnote sheet (Nov 1): on a phone the instrument is the interface and
77|// the evidence comes to the sentence. A tap on a footnote number opens the
78|// cited entry with the verified quote marked inside its text, the criteria
79|// that entry evidences in the gate record, and the gate's stamp on the
80|// sentence. Pure data over the case and the stored result; the page draws it.
81|export interface FootnoteSheet {
82|  n: number;
83|  total: number;
84|  entry: { id: string; date: string; kind: string; text: string } | null;
85|  sentence: string;
86|  quote: string;
87|  // the entry's text split around the quote; match is empty when the quote is not found as written
88|  before: string;
89|  match: string;
90|  after: string;
91|  criteria: { id: string; text: string }[];
92|  status: RecordStatus;
93|  reason: string;
94|}
95|
96|export function footnoteSheet(c: ViewerCase, r: ViewerResult, n: number): FootnoteSheet | null {
97|  const gate = r.gate;
98|  if (!gate) return null;
99|  const s = gate.sentences[n - 1];
100|  if (!s || n < 1) return null;
101|  const e = c.chart.find(x => x.id === s.citation) ?? null;
102|  let before = '', match = '', after = e?.text ?? '';
103|  if (e && s.quote) {
104|    let i = e.text.indexOf(s.quote);
105|    if (i < 0) i = e.text.toLowerCase().indexOf(s.quote.toLowerCase());
106|    if (i >= 0) { before = e.text.slice(0, i); match = e.text.slice(i, i + s.quote.length); after = e.text.slice(i + s.quote.length); }
107|  }
108|  const ids = new Set(gate.evidence.filter(ev => ev.citation === s.citation).map(ev => ev.criterion));
109|  const criteria = c.criteria.filter(k => ids.has(k.id)).map(k => ({ id: k.id, text: k.text }));
110|  return {
111|    n, total: gate.sentences.length,
112|    entry: e ? { id: e.id, date: e.date, kind: e.kind, text: e.text } : null,
113|    sentence: s.text, quote: s.quote, before, match, after, criteria, status: s.status, reason: s.reason,
114|  };
