1|// The paper's figures and tables, read out of README.md at build time so the
2|// viewer's Figures tab can never drift from the paper. A figure line in the
3|// README is `- Figure N. Title: [link text](href). Caption.`; a table opens a
4|// paragraph as `**Table N. Title.** Caption...`. Links to the live page become
5|// in-page hashes (a frame of this replay); links to files in the repository
6|// and to sections of the README go to GitHub. Pure: no DOM, no I/O.
7|
8|export const README_URL = 'https://github.com/jamesrosing/your-procedure-is-denied';
9|export const REPO_BLOB_URL = `${README_URL}/blob/main/`;
10|const DEMO_HASH = /^https:\/\/demo\.hemeehr\.com\/?#/;
11|
12|export interface CaptionSegment { text: string; href?: string; inPage?: boolean }
13|export interface PaperFigure { n: number; title: string; anchor: string; segments: CaptionSegment[] }
14|export interface PaperTable { n: number; title: string; caption: string; anchor: string; href: string }
15|export interface PaperIndex { figures: PaperFigure[]; tables: PaperTable[] }
16|
17|// GitHub's anchor for a heading: lowercase, punctuation dropped, spaces to hyphens.
18|export function githubAnchor(heading: string): string {
19|  return heading.trim().toLowerCase().replace(/[^\p{L}\p{N}\s-]/gu, '').replace(/\s+/g, '-');
20|}
21|
22|function resolveHref(href: string): { href: string; inPage: boolean } {
23|  if (DEMO_HASH.test(href)) return { href: `#${href.slice(href.indexOf('#') + 1)}`, inPage: true };
24|  if (/^[a-z]+:/i.test(href)) return { href, inPage: false };
25|  return { href: `${REPO_BLOB_URL}${href.replace(/^\.?\//, '')}`, inPage: false };
26|}
27|
28|// Markdown links in a line, as plain segments around linked ones.
29|function segmentsOf(line: string): CaptionSegment[] {
30|  const out: CaptionSegment[] = [];
31|  const re = /\[([^\]]+)\]\(([^)\s]+)\)/g;
32|  let last = 0;
33|  for (let m = re.exec(line); m !== null; m = re.exec(line)) {
34|    if (m.index > last) out.push({ text: line.slice(last, m.index) });
35|    out.push({ text: m[1] ?? '', ...resolveHref(m[2] ?? '') });
36|    last = m.index + m[0].length;
37|  }
38|  if (last < line.length) out.push({ text: line.slice(last) });
39|  return out;
40|}
41|
42|function firstSentence(text: string): string {
43|  const m = /^(.*?[.!?])(?:\s|$)/.exec(text.trim());
44|  return m?.[1] ?? text.trim();
45|}
46|
47|export function paperIndex(readme: string): PaperIndex {
48|  const figures: PaperFigure[] = [];
49|  const tables: PaperTable[] = [];
50|  const headings: { number: string; anchor: string }[] = [];
51|  let anchor = '';
52|  for (const raw of readme.split('\n')) {
53|    const line = raw.trimEnd();
54|    const h = /^#{2,3}\s+(.+)$/.exec(line);
55|    if (h) {
56|      anchor = githubAnchor(h[1] ?? '');
57|      const num = /^(\d+(?:\.\d+)*)\.?\s/.exec(h[1] ?? '');
58|      if (num) headings.push({ number: num[1] ?? '', anchor });
59|      continue;
60|    }
61|    const fig = /^- Figure (\d+)\. (.+)$/.exec(line);
62|    if (fig) {
63|      const body = fig[2] ?? '';
64|      const segments = segmentsOf(body);
65|      const plain = segments.map(s => s.text).join('');
66|      const colon = plain.indexOf(':');
67|      const title = (colon > 0 && colon < 90 ? plain.slice(0, colon) : firstSentence(plain).replace(/\.$/, '')).trim();
68|      if (!segments.some(s => s.href)) {
69|        // No link: a figure that names a section of the paper links to that section.
70|        const ref = /section (\d+(?:\.\d+)*)/.exec(plain);
71|        const target = ref ? headings.find(x => x.number === ref[1]) : undefined;
72|        if (target) {
73|          const at = plain.indexOf(ref![0]);
74|          segments.splice(0, segments.length, { text: plain.slice(0, at) }, { text: ref![0], href: `${README_URL}#${target.anchor}`, inPage: false }, { text: plain.slice(at + ref![0].length) });
75|        }
76|      }
77|      figures.push({ n: Number(fig[1]), title, anchor, segments: segments.filter(s => s.text.length > 0) });
78|      continue;
79|    }
80|    const tab = /^\*\*Table (\d+)\. ([^*]+?)\.?\*\*\s*(.*)$/.exec(line);
81|    if (tab) {
82|      const caption = firstSentence(segmentsOf(tab[3] ?? '').map(s => s.text).join('').replace(/`/g, ''));
83|      tables.push({ n: Number(tab[1]), title: (tab[2] ?? '').trim(), caption, anchor, href: `${README_URL}#${anchor}` });
84|    }
85|  }
86|  return { figures, tables };
87|}

