1|// Mutation test of the gate. The nine kept runs hold about 2,200 sentences the
2|// gate verified and none it refuted, because no model fabricated anything. So
3|// the only way to measure what the gate catches is to inject fabrications into
4|// sentences it has already verified and count what gets through.
5|//
6|// Three classes, reported separately:
7|//   hard       a fact the gate is built to check is corrupted: a number replaced
8|//              by a value absent from every admissible source, a date shifted,
9|//              a side swapped, a side added that the cited entry carries only
10|//              inside an idiom ("right back to baseline"; Oct 31), a citation
11|//              moved to an entry that lacks the quote, a word dropped from the
12|//              quote. Every pass here is a gate defect.
13|//   collision  a wrong number or side that happens to appear in the criteria,
14|//              the denial, the case facts, or elsewhere in the cited entry. The
15|//              gate checks presence, not correspondence, so these pass by design;
16|//              the count is the size of that gap.
17|//   soft       a corruption with no hard token in it: a negation flipped, a
18|//              pronoun swapped. The gate is not built to see these; the count is
19|//              the referential limit with a number on it.
20|//
21|// Nothing here changes the gate. It is a measurement.
22|//
23|//   npm run mutate -- [--seed 2026] [--out results/mutations/report.json]
24|import { mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
25|import { parseArgs } from 'node:util';
26|import { dirname, join } from 'node:path';
27|import { fileURLToPath, pathToFileURL } from 'node:url';
28|import { litmus, LITMUS_VERSION, type GateEntry, type GateSources, type SentenceStatus } from '../src/litmus.js';
29|import { gateSources, loadCases, type CaseResult } from '../src/harness.js';
30|import { Rng, addDays } from '../src/synthetic/rng.js';
31|
32|export type MutationKind =
33|  | 'number-absent'
34|  | 'date-shift'
35|  | 'laterality-swap'
36|  | 'laterality-idiom-leak'
37|  | 'citation-moved'
38|  | 'quote-word-dropped'
39|  | 'number-collision'
40|  | 'laterality-collision'
41|  | 'negation-flip'
42|  | 'pronoun-swap';
43|export type MutationClass = 'hard' | 'collision' | 'soft';
44|export interface Sentence { text: string; citation: string; quote: string }
45|export interface Mutation { kind: MutationKind; class: MutationClass; sentence: Sentence; note: string }
46|export interface MutationRecord { kind: MutationKind; class: MutationClass; status: SentenceStatus }
