1|// Small-count statistics for the Results section: the Wilson score interval
2|// for a proportion and the rule of three for a rate observed zero times. Pure
3|// functions, no dependencies; the build-log script prints them.
4|
5|export function wilson(k: number, n: number, z = 1.959964): [number, number] {
6|  if (n <= 0 || k < 0 || k > n) throw new Error(`wilson: k=${k} n=${n}`);
7|  const p = k / n;
8|  const z2 = z * z;
9|  const denom = 1 + z2 / n;
10|  const center = p + z2 / (2 * n);
11|  const half = z * Math.sqrt((p * (1 - p)) / n + z2 / (4 * n * n));
12|  const snap = (x: number): number => (Math.abs(x) < 1e-12 ? 0 : Math.abs(1 - x) < 1e-12 ? 1 : x);
13|  const lo = snap(Math.max(0, (center - half) / denom));
14|  const hi = snap(Math.min(1, (center + half) / denom));
15|  return [lo, hi];
16|}
17|
18|// With zero events in n independent trials, the 95 percent upper bound on the
19|// event rate is about 3/n.
20|export function ruleOfThree(n: number): number {
21|  if (n <= 0) throw new Error(`ruleOfThree: n=${n}`);
22|  return 3 / n;
23|}
24|
25|export function formatInterval(k: number, n: number): string {
26|  const [lo, hi] = wilson(k, n);
27|  return `${Math.round(lo * 100)} to ${Math.round(hi * 100)}%`;
28|}

