1|// Replay logic for the judge-facing viewer: pure functions over a results
2|// file and the synthetic case it was run on. No DOM here, so the tests run
3|// under node and the page is a thin renderer over `stateAt`.
4|//
5|// A case replays as an ordered list of steps: entries read (one per tool call
6|// in an agentic trace, or all cited entries at once for a non-agentic run),
7|// then each piece of evidence attaching to its criterion, then each sentence
8|// with the gate's stamp, then the verdict. The state at step k is the fold of
9|// steps 0..k, so play, pause, and step are a cursor over the list.
10|
11|export interface ViewerEntry {
12|  id: string;
13|  date: string;
14|  kind: string;
15|  text: string;
16|}
17|
18|export interface ViewerCriterion {
19|  id: string;
20|  text: string;
21|}
22|
23|export interface ViewerCase {
24|  id: string;
25|  category: string;
26|  setting: string;
27|  stakesUsd: number;
28|  patient: { alias: string; age: number; sex: string };
29|  procedure: { code: string; codeSystem: string; description: string };
30|  payer: { name: string; planType: string };
31|  denial: { carc: string; carcText?: string; rarc?: string; text: string; dateOfService: string; serviceEnd?: string };
32|  criteria: ViewerCriterion[];
33|  chart: ViewerEntry[];
34|  expected: { warranted: boolean; subtype?: string; support: Record<string, string[]>; note: string };
35|}
36|
37|export type RecordStatus = 'verified' | 'unresolved' | 'refuted' | 'needs-citation' | 'error';
38|
39|export interface TraceEvent {
40|  step: number;
41|  tool: string; // list_entries, read_entry, policy_status
42|  input: Record<string, unknown>;
43|  entryId?: string;
44|  atMs: number; // since the case started
45|  ok: boolean;
46|  live?: boolean; // a query against an external data source, labeled in the viewer
47|  note?: string;
48|  why?: string; // the model's one-sentence reason for the call (the API returns only redacted thinking, so the tool input carries it)
49|  repair?: number; // the repair turn this call was made in; absent for the first turn
50|}
51|
52|// One repair turn (harness --repair): the gate's reasons sent back verbatim,
53|// the revised draft's gate, and what the turn cost. Offered only on a blocked draft.
54|export interface RepairRecord {
55|  turn: number;
56|  reasons: string[];
57|  sent: string;
58|  latencyMs: number;
59|  costUsd: number;
60|  gate?: ViewerResult['gate'];
61|  outcome?: string;
62|  error?: string;
63|}
64|
65|export interface ViewerResult {
66|  caseId: string;
67|  category: string;
68|  outcome: string;
69|  latencyMs: number;
70|  costUsd: number;
71|  error?: string;
72|  draft?: {
73|    warranted: boolean;
74|    reason?: string;
75|    evidence: { criterion: string; citation: string; quote: string }[];
76|    sentences: { text: string; citation: string; quote: string }[];
77|  };
78|  gate?: {
79|    litmus?: string; // the gate version string recorded with the verdict
80|    inputHash?: string; // sha256 of the sources and the draft, for the provenance record
81|    verdict: 'pass' | 'blocked' | 'declined';
82|    reasons: string[];
83|    declinedReason?: string;
84|    sentences: { index: number; text: string; citation: string; quote: string; status: RecordStatus; reason: string }[];
85|    evidence: { index: number; criterion: string; citation: string; quote: string; status: RecordStatus; reason: string }[];
86|    criteria: Record<string, 'verified' | 'unverified'>;
87|  };
88|  trace?: TraceEvent[];
89|  reading?: { entriesRead: number; chartSize: number; supportRead: number; supportTotal: number };
90|  // the advisor's opinion per criterion, with the model's name; never a gate input
91|  advice?: { provider: string; model: string; items: { criterion: string; verdict: 'supports' | 'partial' | 'silent'; why: string }[]; error?: string };
92|  // --repair runs: the outcome above is scored on the final gate; these keep the no-repair result
93|  firstOutcome?: string;
94|  firstGate?: ViewerResult['gate']; // present only when a repair turn happened
95|  repairs?: RepairRecord[];
96|}
97|
98|export type Side = 'payer' | undefined; // absent: the physician's side, the default
99|
100|export interface ResultsFile {
101|  run: { startedAt: string; provider: string; model: string; effort: string; cases: number; agentic?: boolean; side?: 'payer'; repair?: number };
102|  summary: {
103|    cases: number;
104|    outcomes: Record<string, number>;
105|    agreementRate: number;
106|    sentencesVerified: number;
107|    ungroundedSentencesCaught: number;
108|    latencyMs: { p50: number };
109|    costUsd: { perCase: number };
110|    reading?: { entriesReadPerCase: number; chartSizePerCase: number; supportCoverage: number };
111|  };
112|  results: ViewerResult[];
113|}
114|
115|export type Step =
116|  | { kind: 'read'; entryId: string; tool: string; live: boolean; note?: string; why?: string; repair?: number; atMs: number }
117|  | { kind: 'lookup'; tool: string; note: string; live: boolean; input?: LookupQuestion; why?: string; repair?: number; atMs: number }
118|  | { kind: 'read-all'; entryIds: string[]; atMs: number }
119|  | { kind: 'evidence'; criterion: string; citation: string; quote: string; status: RecordStatus; reason: string; atMs: number }
120|  // previous: the stamp this sentence carried before a repair turn re-stamped it; the reason is shown between the two
121|  | { kind: 'sentence'; index: number; text: string; citation: string; quote: string; status: RecordStatus; reason: string; previous?: { status: RecordStatus; reason: string }; repair?: number; atMs: number }
122|  // the repair turn: the gate's reasons go back to the model verbatim; `sentences` is the revised draft's count
123|  | { kind: 'repair'; turn: number; reasons: string[]; sentences: number; atMs: number }
124|  | { kind: 'advice'; model: string; items: { criterion: string; verdict: 'supports' | 'partial' | 'silent'; why: string }[]; atMs: number }
125|  | { kind: 'verdict'; verdict: 'pass' | 'blocked' | 'declined' | 'error'; reasons: string[]; declinedReason?: string; blockedSentence?: number; error?: string; repair?: number; atMs: number };
126|
127|export interface CriterionState {
128|  id: string;
129|  text: string;
130|  status: 'pending' | 'verified' | 'unverified';
131|  evidence: { citation: string; quote: string; status: RecordStatus; reason: string }[];
132|  advice?: { model: string; verdict: 'supports' | 'partial' | 'silent'; why: string }; // the advisor's opinion, shown after the gate
133|}
134|
135|export interface SentenceState {
136|  index: number;
137|  text: string;
138|  citation: string;
139|  quote: string;
140|  status: RecordStatus;
141|  reason: string;
142|  previous?: { status: RecordStatus; reason: string }; // the stamp before a repair turn re-stamped this sentence
143|}
144|
145|export interface ReplayState {
146|  cursor: number; // steps applied so far; 0 is the untouched chart
147|  total: number;
148|  read: string[]; // entry ids lit, in the order they were read
149|  open: string | null; // the entry whose text is slid open, the last one read
150|  lookups: { tool: string; note: string; live: boolean; input?: LookupQuestion }[];
151|  strip: LookupStrip | null; // the live CHART query as a strip, only while it is the last step applied
152|  criteria: CriterionState[];
153|  sentences: SentenceState[];
154|  verdict: Extract<Step, { kind: 'verdict' }> | null;
155|  repair: { turn: number; reasons: string[] } | null; // the repair turn in progress or just finished
156|  why: { entryId: string | null; text: string; live: boolean } | null; // the model's reason for the last read or query, while that step is the last applied
157|  counters: { entriesRead: number; chartSize: number; sentencesVerified: number; sentencesTotal: number; costUsd: number; elapsedMs: number };
158|  done: boolean;
159|}
160|
161|// The payer's own reason for the denial, the sentence after "Payer remark:" in
162|// the denial text, so the viewer can set the insurer's claim above the
163|// criteria and the record's quotes that answer it. Null when the denial
164|// carries no remark.
165|export function payerRemark(c: ViewerCase): string | null {
166|  const m = /Payer remark:\s*(.+)$/s.exec(c.denial.text);
167|  const r = m?.[1]?.trim();
168|  return r && r.length > 0 ? r : null;
169|}
170|
171|// A deep link may name a step: `&step=7` or `&step=end`, so a figure in the
172|// paper can point at one frame of a replay. Clamped to the timeline; null when
173|// absent or unreadable.
174|export function parseStep(value: string | null, total: number): number | null {
175|  if (value === null) return null;
176|  const v = value.trim();
177|  if (v === '') return null;
178|  if (v.toLowerCase() === 'end') return total;
179|  const n = Number.parseInt(v, 10);
180|  if (Number.isNaN(n)) return null;
181|  return Math.max(0, Math.min(n, total));
182|}
183|
184|// Plain-words help for the labels in the case header, shown on hover; the
185|// narration says the same once. Two cold readers asked what the labels were.
186|export const LABEL_HELP: Record<string, string> = {
187|  model: 'The Meta model that drafted this appeal.',
188|  provider: 'Where the model ran: meta is the Meta Model API; baseten is the open-weights model on Baseten.',
189|  effort: 'The reasoning effort the model was asked for. The kept runs used low; the effort sweep (post hoc, README Table 6) ran medium and high.',
190|  repair: 'A post hoc run in which a blocked draft was sent back to the model once with the gate\u2019s reasons, verbatim, and the revised draft re-gated (README Table 5). The outcome shown is the final one; the first stamp of each re-stamped sentence is kept in the replay.',
191|  record: 'A hash of the record alone: the chart, the criteria, the denial, and the case facts, with no draft in it. A live run of this case in a terminal (npm run live) prints the same value, which is how a reader can tell the two are on the same record.',
192|  run: 'The date of this run.',
193|  gate: 'The version of the deterministic check that verifies every sentence against the chart.',
194|  synthetic: 'A synthetic patient and chart; no real record appears anywhere in this repository.',
195|  stakes: 'An approximate dollar value of the service that was denied.',
196|  category: 'The area of care this denial falls in.',
197|};
198|
199|// What kind of denial this is, in the case header. Every case in the set is a
200|// claim denied after the service was given: the payer's remittance with a
201|// claim adjustment reason code. None is a prior-authorization request. The
202|// three CARC 197 cases are claims denied because no authorization was on file.
203|export function denialKind(c: ViewerCase): string {
204|  const when = c.denial.serviceEnd ? `${c.denial.dateOfService} to ${c.denial.serviceEnd}` : `on ${c.denial.dateOfService}`;
205|  if (c.denial.carc === '197') return `claim denied, no authorization on file, for care ${when}`;
206|  return `claim denied after the service, given ${when}`;
207|}
208|
209|export const DENIAL_KIND_HELP = "Every case here is a claim denied after the service was given: the payer's remittance carrying a claim adjustment reason code. None is a prior-authorization request. Three claims (CARC 197) were denied because no authorization was on file; two plans allow a retrospective medical-necessity review and the chart answers it, and one plan refuses that review, so a medical-necessity appeal is the wrong instrument.";
210|
211|// One line under each column header saying what the column holds, and what
212|// the stamps in it mean. The draft column says what PASS is not.
213|export const PANEL_HELP = {
214|  chart: "The physician's record for this patient: dated entries in dictation voice, about half of them unrelated to the denial. An entry lights when the model reads it.",
215|  criteria: "The payer's written coverage rules for this service, under the payer's own reason for the denial. A criterion lights when the draft cites verified evidence for it.",
216|  draft: "The appeal the model drafts to this denial, one sentence at a time, each stamped by the gate against the chart. PASS means every sentence is in the record, not that the appeal would prevail.",
217|} as const;
218|
219|// The words that change with the chair. On the payer side (build/results/payer/,
220|// README Table 4) the draft is the plan's determination, a verified PASS is a
221|// determination whose every sentence is in the record, DECLINED is the model
222|// declining to deny, and there is no writ: the instrument is the physician's.
223|export interface SideText {
224|  side: Side;
225|  draftHeading: string;
226|  draftHelp: string;
227|  passHead: (verified: number, total: number) => string;
228|  declinedHead: string;
229|  outcome: (o: string) => string;
230|  writ: boolean;
231|  stamp?: string; // a label for the context line
232|}
233|
234|export function sideText(side: Side): SideText {
235|  if (side === 'payer') {
236|    return {
237|      side,
238|      draftHeading: 'Draft determination',
239|      draftHelp: "The plan's written claim determination the model drafts, arguing the insurer's side, one sentence at a time, each stamped by the gate against the same chart. PASS means every sentence is in the record, not that the denial is right: whether the record fails the criterion is a reading the gate does not make.",
240|      passHead: (verified, total) => `${verified} of ${total} sentences verified against the chart; a determination held to the record, and the reading of the criterion is not the gate's to make`,
241|      declinedHead: 'the model read the chart and declined to deny',
242|      outcome: o => ({ 'correct-pass': 'determination verified', 'correct-decline': 'declined to deny', blocked: 'blocked', missed: 'did not deny a failing record', 'false-pass': 'determination against a supporting record', error: 'error' }[o] ?? o),
243|      writ: false,
244|      stamp: 'payer side, post hoc',
245|    };
246|  }
247|  return {
248|    side,
249|    draftHeading: 'Draft appeal',
250|    draftHelp: PANEL_HELP.draft,
251|    passHead: (verified, total) => `${verified} of ${total} sentences verified against the chart; ready for the physician to read and sign`,
252|    declinedHead: 'the model read the chart and declined to draft',
253|    outcome: o => ({ 'correct-pass': 'passed', 'correct-decline': 'declined', blocked: 'blocked', missed: 'missed', 'false-pass': 'false pass', error: 'error' }[o] ?? o),
254|    writ: true,
255|  };
256|}
257|
258|// The run the page opens on without a deep link: the primary proposer's
259|// (muse-spark-1.3) newest physician-side run that used every tool, by start
260|// time; failing that, any model's newest live run; failing that, the newest run.
261|export const PRIMARY_MODEL = 'muse-spark-1.3';
262|export function newestRun<T extends { startedAt: string; live?: boolean; side?: 'payer'; model?: string }>(runs: readonly T[]): T | undefined {
263|  const own = runs.filter(r => r.side !== 'payer');
264|  const pool = own.length ? own : [...runs];
265|  const newestFirst = [...pool].sort((a, b) => b.startedAt.localeCompare(a.startedAt));
266|  return newestFirst.find(r => r.live && r.model === PRIMARY_MODEL) ?? newestFirst.find(r => r.live) ?? newestFirst[0];
267|}
268|
269|// The result stamp, on hover. PASS is the gate's word, not a verdict on the
270|// appeal: the physician who signs decides whether the record satisfies the criteria.
271|export const VERDICT_HELP = {
272|  pass: "PASS: the model judged that the record supports an appeal, and the gate found every quoted phrase in the entry it cites and every number, date, code, and side sourced. It does not say the record satisfies the criteria or that the appeal would prevail; the physician who reads and signs decides that.",
273|  blocked: "BLOCKED: the model drafted an appeal, and at least one sentence did not verify against the chart, or a criterion had no verified evidence. Nothing leaves. The physician is shown what failed and why.",
274|  declined: "DECLINED: the model read the chart and decided the record does not support a medical-necessity appeal, and said why. For 20 of the 50 cases this is the answer the grading key expects.",
275|  error: "FAILED: the request did not complete, for instance an answer that was not valid JSON, so the gate never ran. The run file keeps the failure.",
276|} as const;
277|
278|// Where the fifty cases came from, for the about panel and the scoreboard.
279|export const DATA_NOTE = "The fifty cases are synthetic, built by a seeded program (build/src/synthetic/generate.ts, seed 20261027) from 18 service templates in the categories where denial dollars concentrate, so the committed files are reproducible and a test checks them against the generator. 30 cases are warranted: the chart documents every criterion. 20 are not: 6 never address a criterion, 7 raise it but fall short, 4 are administrative denials a medical-necessity appeal cannot answer, and 3 are plan exclusions. The six payers are fictional, and their criteria were written for the benchmark from publicly described policy patterns, not any insurer's policy. Each chart is 19 to 35 dated entries in dictation voice, about two thirds of them routine traffic unrelated to the denial. A patient is an alias, an age, and a sex. No real record appears anywhere.";
280|
281|const CODE_SYSTEM_HELP: Record<string, string> = {
282|  HIPPS: 'HIPPS: the billing code for a skilled nursing stay and its level of care.',
283|  CMG: 'CMG: the billing code for an inpatient rehabilitation stay.',
284|  'MS-DRG': 'MS-DRG: the billing code for an inpatient hospital stay.',
285|  CPT: 'CPT: the billing code for the procedure.',
286|  HCPCS: 'HCPCS: the billing code for the drug, device, or service.',
287|};
288|
289|export function codeSystemHelp(codeSystem: string): string {
290|  return CODE_SYSTEM_HELP[codeSystem] ?? `${codeSystem}: the billing code for this service.`;
291|}
292|
293|export function carcHelp(c: ViewerCase): string {
294|  const text = c.denial.carcText ? ` ${c.denial.carcText}` : '';
295|  return `CARC ${c.denial.carc}: the claim adjustment reason code the payer put on the denial.${text}`;
296|}
