201|  const base = Math.round(spot.value);
202|  const candidates = [base + 1, base - 1, base + 2, base + 3, base + 5, base + 7, base * 2 + 1, base + 11, base + 13, base + 17].filter(n => n > 0 && n !== base);
203|  const absentEverywhere = candidates.find(n => !adm.chartWide.has(String(n)) && (!spot.word || WORD_FOR[n] !== undefined));
204|  const absentFromAdmissible = candidates.find(n => !adm.all.has(String(n)) && (!spot.word || WORD_FOR[n] !== undefined));
205|  const value = absentEverywhere ?? absentFromAdmissible;
206|  if (value === undefined) return null;
207|  const text = splice(s.text, spot, render(spot, value));
208|  return { kind: 'number-absent', class: 'hard', sentence: { ...s, text }, note: `${spot.raw} -> ${render(spot, value)}${absentEverywhere === undefined ? ' (present in another entry)' : ''}` };
209|}
210|
211|function numberCollision(s: Sentence, adm: Admissible, rng: Rng): Mutation | null {
212|  const spots = numbersIn(s.text).filter(sp => !sp.word || true);
213|  if (spots.length === 0) return null;
214|  const pool = [...adm.shared].filter(t => /^\d+$/.test(t) && !adm.entry.has(t)).map(Number).filter(n => n > 0).sort((a, b) => a - b);
215|  if (pool.length === 0) return null;
216|  const spot = rng.pick(spots);
217|  const choices = pool.filter(n => n !== Math.round(spot.value) && (!spot.word || WORD_FOR[n] !== undefined));
218|  if (choices.length === 0) return null;
219|  const value = rng.pick(choices);
220|  const text = splice(s.text, spot, render(spot, value));
221|  return { kind: 'number-collision', class: 'collision', sentence: { ...s, text }, note: `${spot.raw} -> ${render(spot, value)} (present in the criteria, denial, or case facts, absent from the entry)` };
222|}
223|
224|function dateShift(s: Sentence, adm: Admissible): Mutation | null {
225|  const iso = [...s.text.matchAll(ISO_DATE_RE)];
226|  if (iso.length > 0) {
227|    const m = iso[0]!;
228|    for (const days of [1, -1, 2, -2]) {
229|      const shifted = addDays(m[0], days);
230|      if (!adm.all.has(shifted)) {
231|        return { kind: 'date-shift', class: 'hard', sentence: { ...s, text: s.text.replace(m[0], shifted) }, note: `${m[0]} -> ${shifted}` };
232|      }
233|    }
234|    return null;
235|  }
236|  const slash = [...s.text.matchAll(SLASH_DATE_RE)];
237|  if (slash.length > 0) {
238|    const m = slash[0]!;
239|    const day = Number(m[2]);
240|    for (const delta of [1, -1]) {
241|      const d = day + delta;
242|      if (d < 1 || d > 28) continue;
243|      const shifted = `${m[1]}/${d}/${m[3]}`;
244|      if (!adm.all.has(shifted)) return { kind: 'date-shift', class: 'hard', sentence: { ...s, text: s.text.replace(m[0], shifted) }, note: `${m[0]} -> ${shifted}` };
245|    }
246|  }
247|  return null;
248|}
249|
250|function sideSpots(text: string): { start: number; end: number; word: string }[] {
251|  const masked = text.replace(SIDE_IDIOM_RE, m => ' '.repeat(m.length));
252|  return [...masked.matchAll(/\b(left|right)\b/gi)].map(m => ({ start: m.index!, end: m.index! + m[0].length, word: m[0] }));
253|}
254|
255|function lateralitySwap(s: Sentence, adm: Admissible): Mutation | null {
256|  const spots = sideSpots(s.text);
257|  if (spots.length === 0) return null;
258|  let text = s.text;
259|  for (const sp of [...spots].reverse()) text = splice(text, sp, matchCase(sp.word, sp.word.toLowerCase() === 'left' ? 'right' : 'left'));
260|  const sides = new Set(spots.map(sp => sp.word.toLowerCase()));
261|  const swappedIn = [...sides].map(w => (w === 'left' ? 'right' : 'left'));
262|  const present = swappedIn.some(w => adm.sidesEntry.has(w) || adm.sidesShared.has(w));
263|  const kind: MutationKind = present ? 'laterality-collision' : 'laterality-swap';
264|  return { kind, class: CLASS_OF[kind], sentence: { ...s, text }, note: `${[...sides].join('/')} -> ${swappedIn.join('/')}${present ? ' (the other side already appears in the entry, criteria, denial, or facts)' : ''}` };
265|}
266|
267|// The idiom leak (Oct 31, found in review): a side the cited entry carries only
268|// inside an idiom is added to a sentence that named none. Under gate v1.4 the
269|// entry's idiom made the word admissible and the sentence was verified. Only
270|// attempted where the word is a side nowhere in the entry, the criteria, the
271|// denial, or the facts, so a pass is the leak and nothing else.
272|function lateralityIdiomLeak(s: Sentence, entry: GateEntry, adm: Admissible): Mutation | null {
273|  if (sideSpots(s.text).length > 0) return null;
274|  const leaked = idiomSides(entry.text).find(w => !adm.sidesEntry.has(w) && !adm.sidesShared.has(w));
275|  if (!leaked) return null;
276|  const text = s.text.endsWith('.') ? `${s.text.slice(0, -1)} on the ${leaked} side.` : `${s.text} on the ${leaked} side`;
277|  return { kind: 'laterality-idiom-leak', class: 'hard', sentence: { ...s, text }, note: `"${leaked}" added; the entry has the word only in an idiom` };
278|}
279|
280|function citationMoved(s: Sentence, sources: GateSources, rng: Rng): Mutation | null {
281|  const q = canon(s.quote);
282|  const others = sources.chart.filter(e => e.id !== s.citation && !canon(e.text).includes(q));
283|  if (others.length === 0) return null;
284|  const target = rng.pick(others);
285|  return { kind: 'citation-moved', class: 'hard', sentence: { ...s, citation: target.id }, note: `${s.citation} -> ${target.id}` };
286|}
287|
288|function quoteWordDropped(s: Sentence, entry: GateEntry, rng: Rng): Mutation | null {
289|  const words = s.quote.split(' ');
290|  if (words.length < 3) return null;
291|  const entryText = canon(entry.text);
292|  for (const i of rng.shuffle(words.map((_, i) => i))) {
293|    const candidate = [...words.slice(0, i), ...words.slice(i + 1)].join(' ');
294|    if (entryText.includes(canon(candidate))) continue;
295|    const text = s.text.includes(s.quote) ? s.text.replace(s.quote, candidate) : s.text;
296|    return { kind: 'quote-word-dropped', class: 'hard', sentence: { ...s, text, quote: candidate }, note: `dropped "${words[i]}"` };
297|  }
298|  return null;
299|}
300|
301|const NEGATION_FLIPS: [RegExp, string][] = [
302|  [/\bwithout\b/, 'with'],
303|  [/\bno further\b/, 'further'],
304|  [/\bnot\s+/, ''],
305|  [/\bimproved\b/, 'worsened'],
306|  [/\bimprovement\b/, 'decline'],
307|  [/\bexceeds\b/, 'falls short of'],
308|  [/\bexceeded\b/, 'fell short of'],
309|  [/\bexceeding\b/, 'falling short of'],
310|  [/\bmeets\b/, 'does not meet'],
311|  [/\bmet\b/, 'did not meet'],
312|  [/\bdocuments\b/, 'does not document'],
313|  [/\bdocumented\b/, 'never documented'],
314|  [/\bconfirms\b/, 'does not confirm'],
315|  [/\bconfirmed\b/, 'did not confirm'],
316|  [/\bshows\b/, 'does not show'],
317|  [/\bdemonstrates\b/, 'does not demonstrate'],
318|  [/\brequired\b/, 'did not require'],
319|  [/\brequires\b/, 'does not require'],
320|  [/\btolerated\b/, 'did not tolerate'],
321|  [/\bfailed\b/, 'succeeded with'],
322|  [/\b(is|was|were|has|had|does|did)\b(?!\s+not\b)/, '$1 not'],
323|  [/\bwith\b/, 'without'],
324|];
325|
326|function negationFlip(s: Sentence): Mutation | null {
327|  for (const [re, rep] of NEGATION_FLIPS) {
328|    if (re.test(s.text)) {
329|      const text = s.text.replace(re, rep).replace(/\s{2,}/g, ' ');
330|      if (text === s.text) continue;
331|      return { kind: 'negation-flip', class: 'soft', sentence: { ...s, text }, note: `${re.source} -> "${rep}"` };
332|    }
333|  }
334|  return null;
335|}
336|
337|const PRONOUNS: Record<string, string> = { he: 'she', she: 'he', his: 'her', her: 'his', him: 'her', himself: 'herself', herself: 'himself' };
338|
339|function pronounSwap(s: Sentence): Mutation | null {
340|  const re = /\b(he|she|his|her|him|himself|herself)\b/gi;
341|  if (!re.test(s.text)) return null;
342|  const text = s.text.replace(re, w => matchCase(w, PRONOUNS[w.toLowerCase()]!));
343|  return { kind: 'pronoun-swap', class: 'soft', sentence: { ...s, text }, note: 'he/she, his/her, him/her swapped' };
344|}
345|
346|export function mutateSentence(s: Sentence, sources: GateSources, rng: Rng): Mutation[] {
347|  const entry = sources.chart.find(e => e.id === s.citation);
348|  if (!entry) return [];
349|  const adm = admissible(sources, entry);
350|  const out: Mutation[] = [];
351|  const push = (m: Mutation | null) => { if (m) out.push(m); };
352|  push(numberAbsent(s, adm, rng));
353|  push(dateShift(s, adm));
354|  push(lateralitySwap(s, adm));
355|  push(lateralityIdiomLeak(s, entry, adm));
356|  push(citationMoved(s, sources, rng));
357|  push(quoteWordDropped(s, entry, rng));
358|  push(numberCollision(s, adm, rng));
359|  push(negationFlip(s));
360|  push(pronounSwap(s));
361|  return out;
362|}
363|
364|export function gateMutation(sources: GateSources, m: Mutation): { status: SentenceStatus; reason: string } {
365|  const r = litmus(sources, { warranted: true, evidence: [], sentences: [m.sentence] });
366|  const s = r.sentences[0]!;
367|  return { status: s.status, reason: s.reason };
368|}
369|
370|export interface KindSummary { attempted: number; caught: number; passed: number; statuses: Partial<Record<SentenceStatus, number>> }
371|export interface ClassSummary { attempted: number; caught: number; passed: number }
372|export interface MutationSummary { byKind: Partial<Record<MutationKind, KindSummary>>; byClass: Record<MutationClass, ClassSummary> }
373|
374|export function summarizeMutations(records: MutationRecord[]): MutationSummary {
375|  const byKind: Partial<Record<MutationKind, KindSummary>> = {};
376|  const byClass: Record<MutationClass, ClassSummary> = { hard: { attempted: 0, caught: 0, passed: 0 }, collision: { attempted: 0, caught: 0, passed: 0 }, soft: { attempted: 0, caught: 0, passed: 0 } };
377|  for (const r of records) {
378|    const k = (byKind[r.kind] ??= { attempted: 0, caught: 0, passed: 0, statuses: {} });
379|    const caught = r.status !== 'verified';
380|    k.attempted += 1;
381|    if (caught) k.caught += 1; else k.passed += 1;
382|    k.statuses[r.status] = (k.statuses[r.status] ?? 0) + 1;
383|    const c = byClass[r.class];
384|    c.attempted += 1;
385|    if (caught) c.caught += 1; else c.passed += 1;
386|  }
387|  return { byKind, byClass };
388|}
389|
390|// --- the run over the kept results
391|
392|interface ResultsFile { run: { model: string; provider: string; litmus?: string }; results: CaseResult[] }
393|interface FullRecord extends MutationRecord { file: string; caseId: string; sentence: number; note: string; reason: string; before: Sentence; after: Sentence }
394|
395|async function main(): Promise<void> {
396|  const { values } = parseArgs({ options: { seed: { type: 'string', default: '2026' }, out: { type: 'string' } } });
397|  const here = dirname(fileURLToPath(import.meta.url));
398|  const resultsDir = join(here, '..', 'results');
399|  const cases = new Map(loadCases(join(here, '..', 'synthetic', 'cases')).map(c => [c.id, c]));
400|  const files = readdirSync(resultsDir).filter(f => f.endsWith('.json')).sort();
401|  const rng = new Rng(Number(values.seed));
402|  const records: FullRecord[] = [];
403|  let drafts = 0;
404|  let verified = 0;
405|  for (const file of files) {
406|    const parsed = JSON.parse(readFileSync(join(resultsDir, file), 'utf8')) as ResultsFile;
407|    for (const r of parsed.results) {
408|      if (!r.gate || !r.draft) continue;
409|      const c = cases.get(r.caseId);
410|      if (!c) throw new Error(`case ${r.caseId} not found`);
411|      const sources = gateSources(c);
412|      drafts += 1;
413|      r.gate.sentences.forEach((s, index) => {
414|        if (s.status !== 'verified') return;
415|        verified += 1;
416|        const sentence = { text: s.text, citation: s.citation, quote: s.quote };
417|        for (const m of mutateSentence(sentence, sources, rng)) {
418|          const g = gateMutation(sources, m);
419|          records.push({ file, caseId: r.caseId, sentence: index, kind: m.kind, class: m.class, status: g.status, reason: g.reason, note: m.note, before: sentence, after: m.sentence });
420|        }
421|      });
422|    }
423|  }
424|  const summary = summarizeMutations(records);
425|  const misses = records.filter(r => r.class === 'hard' && r.status === 'verified');
426|  const collisionPasses = records.filter(r => r.class === 'collision' && r.status === 'verified');
427|  const softPasses = records.filter(r => r.class === 'soft' && r.status === 'verified');
428|  const example = (kind: MutationKind, status: 'verified' | 'caught') => records.find(r => r.kind === kind && (status === 'verified' ? r.status === 'verified' : r.status !== 'verified'));
429|  const report = {
430|    generatedAt: new Date().toISOString(),
431|    seed: Number(values.seed),
432|    gate: LITMUS_VERSION,
433|    corpus: { files, drafts, verifiedSentences: verified, mutations: records.length },
434|    summary,
435|    misses,
436|    collisionPasses,
437|    collisionCaughtSample: records.filter(r => r.class === 'collision' && r.status !== 'verified').slice(0, 15),
438|    softPassSample: softPasses.slice(0, 25),
439|    caughtExamples: (['number-absent', 'date-shift', 'laterality-swap', 'laterality-idiom-leak', 'citation-moved', 'quote-word-dropped'] as MutationKind[]).map(k => example(k, 'caught')).filter(Boolean),
440|  };
441|  const out = values.out ? values.out : join(resultsDir, 'mutations', 'report.json');
442|  mkdirSync(dirname(out), { recursive: true });
443|  writeFileSync(out, JSON.stringify(report, null, 2) + '\n');
444|
445|  const pct = (n: number, d: number) => (d === 0 ? '-' : `${((100 * n) / d).toFixed(1)}%`);
446|  console.log(`corpus: ${files.length} kept runs, ${drafts} gated drafts, ${verified} verified sentences, ${records.length} mutations; seed ${values.seed}; ${LITMUS_VERSION.split(':')[0]}`);
447|  console.log('');
448|  console.log(`${'kind'.padEnd(22)} ${'class'.padEnd(10)} ${'attempted'.padStart(9)} ${'caught'.padStart(7)} ${'passed'.padStart(7)}  caught%  statuses`);
449|  for (const [kind, k] of Object.entries(summary.byKind)) {
450|    console.log(`${kind.padEnd(22)} ${CLASS_OF[kind as MutationKind].padEnd(10)} ${String(k!.attempted).padStart(9)} ${String(k!.caught).padStart(7)} ${String(k!.passed).padStart(7)}  ${pct(k!.caught, k!.attempted).padStart(6)}  ${Object.entries(k!.statuses).map(([s, n]) => `${s} ${n}`).join(', ')}`);
451|  }
452|  console.log('');
453|  for (const [cls, c] of Object.entries(summary.byClass)) console.log(`${cls.padEnd(10)} attempted ${c.attempted}, caught ${c.caught} (${pct(c.caught, c.attempted)}), passed ${c.passed}`);
454|  console.log('');
455|  console.log(`hard-class misses (gate defects if any): ${misses.length}`);
456|  for (const m of misses.slice(0, 40)) console.log(`  ${m.file.slice(0, 30)} ${m.caseId} s${m.sentence} ${m.kind} ${m.note}\n    before: ${m.before.text}\n    after:  ${m.after.text}`);
457|  console.log(`wrote ${out}`);
458|}
459|
460|if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
461|  main().catch((error: unknown) => {
462|    console.error(error instanceof Error ? `${error.constructor.name}: ${error.message}` : String(error));
463|    process.exit(1);
464|  });
465|}

