404|    first.dataset['status'] = previous.status;
405|    first.append(text('b', '', `first ${stampText(previous.status)}`), text('span', '', ` ${previous.reason}`), text('span', 'then', ` \u2192 after the repair turn ${stampText(s.status)}`));
406|    why.append(first);
407|  }
408|  if (s.status === 'verified') {
409|    why.append(text('b', '', 'verified '), text('span', 'src', `${s.citation}: `), (() => { const q = document.createElement('q'); q.textContent = s.quote; return q; })());
410|  } else {
411|    why.append(text('b', '', `${recheckLabel(s.status)} `), text('span', '', `${s.reason} (cited ${s.citation})`));
412|  }
