419|  if (existing > state.sentences.length) ui.sentences.replaceChildren();
420|  // A repair turn re-stamps a sentence in place: the row stays, its stamp and
421|  // reason change, and the first stamp is kept above the new one.
422|  for (let i = 0; i < Math.min(ui.sentences.children.length, state.sentences.length); i++) {
423|    const li = ui.sentences.children[i] as HTMLElement;
424|    const s = state.sentences[i]!;
425|    const o = originals.get(li);
426|    if (!o || li.dataset['editing'] || (o.status === s.status && o.reason === s.reason && o.text === s.text && o.citation === s.citation && o.quote === s.quote)) continue;
427|    const original: SentenceOriginal = { text: s.text, citation: s.citation, quote: s.quote, status: s.status, reason: s.reason };
428|    originals.set(li, original);
429|    li.dataset['status'] = s.status;
430|    li.classList.add('restamped');
431|    li.querySelector<HTMLElement>('.text')!.textContent = s.text;
432|    li.querySelector<HTMLElement>('.stamp')!.textContent = stampText(s.status);
433|    fillWhy(li.querySelector<HTMLElement>('.why')!, original, s.previous);
434|  }
435|  for (const s of state.sentences.slice(ui.sentences.children.length)) {
436|    const li = document.createElement('li');
437|    li.className = 'sentence';
438|    li.dataset['status'] = s.status;
439|    li.dataset['index'] = String(s.index);
440|    const original: SentenceOriginal = { text: s.text, citation: s.citation, quote: s.quote, status: s.status, reason: s.reason };
441|    originals.set(li, original);
