524|export function stateAt(steps: Step[], result: ViewerResult, c: ViewerCase, cursor: number): ReplayState {
525|  const k = Math.max(0, Math.min(cursor, steps.length));
526|  let state = initialState(steps, result, c);
527|  for (let i = 0; i < k; i++) state = apply(state, steps[i]!, result, c);
528|  state.cursor = k;
529|  state.done = k >= steps.length;
530|  return state;
