533|// Milliseconds of wall-clock to wait between two steps when playing. Model
534|// latency is compressed so a 16 second call replays in a few seconds, with a
535|// floor so each step registers on screen.
536|export function playDelayMs(steps: Step[], cursor: number, speed = 1): number {
537|  const before = cursor > 0 ? steps[cursor - 1] : undefined;
538|  const prev = before?.atMs ?? 0;
539|  const cur = steps[cursor]?.atMs ?? prev;
540|  const real = Math.max(0, cur - prev);
541|  let wait = Math.max(220, Math.min(1400, real / 8));
542|  // A live query is shown as a strip with its answer typed out; hold it long enough to read.
543|  if (before?.kind === 'lookup' && before.live) wait = Math.max(wait, LOOKUP_DWELL_MS);
544|  return wait / speed;
