556|  cases: number;
557|  agreed: number;
558|  blocked: number;
559|  missed: number; // the model declined a case the key labels warranted: a judgment call, not an invented fact
560|  errors: number; // answers that failed before the gate: request errors and unparseable drafts
561|  falsePass: number; // the gate passed a draft on a case the key labels absent or near-miss: the referential limit
562|  sentencesVerified: number;
563|  latencyP50Ms: number;
564|  costPerCaseUsd: number;
565|  entriesRead: number | null; // mean entries read per case, agentic runs only
566|  chartSize: number | null;
567|  supportCoverage: number | null;
