570|export const MODEL_LABELS: Record<string, string> = {
571|  'muse-spark-1.3': 'muse-spark-1.3 (Meta Model API)',
572|  'muse-wonder-1.0': 'muse-wonder-1.0 (Meta Model API)',
573|  'meta-models/muse-spark-open': 'Muse Spark Open (open weights, hosted on Baseten)',
574|  'meta-models/muse-spark-open-1026': 'Muse Spark Open (open weights, hosted on Baseten)',
