577|export function scoreboardRow(file: ResultsFile): ScoreboardRow {
578|  const s = file.summary;
579|  const results = file.results ?? [];
580|  const agentic = file.run.agentic === true || results.some(r => (r.trace?.length ?? 0) > 0);
581|  const live = results.some(r => (r.trace ?? []).some(t => t.live === true));
582|  const reading = results.map(r => r.reading).filter((r): r is NonNullable<ViewerResult['reading']> => !!r);
583|  const mean = (f: (r: NonNullable<ViewerResult['reading']>) => number) => (reading.length ? reading.reduce((a, r) => a + f(r), 0) / reading.length : null);
584|  const supportTotal = reading.reduce((a, r) => a + r.supportTotal, 0);
585|  return {
586|    model: MODEL_LABELS[file.run.model] ?? file.run.model,
587|    provider: file.run.provider,
588|    agentic,
589|    live,
590|    cases: s.cases,
591|    agreed: (s.outcomes['correct-pass'] ?? 0) + (s.outcomes['correct-decline'] ?? 0),
592|    blocked: s.outcomes['blocked'] ?? 0,
593|    missed: s.outcomes['missed'] ?? 0,
594|    errors: s.outcomes['error'] ?? 0,
595|    falsePass: s.outcomes['false-pass'] ?? 0,
596|    sentencesVerified: s.sentencesVerified,
597|    latencyP50Ms: s.latencyMs.p50,
598|    costPerCaseUsd: s.costUsd.perCase,
599|    entriesRead: mean(r => r.entriesRead),
600|    chartSize: mean(r => r.chartSize),
