605|// README order: the primary proposer, the quality ceiling, then open weights; agentic rows after, live-tool rows last.
606|const MODEL_RANK = ['muse-spark-1.3', 'muse-wonder-1.0', 'Muse Spark Open'];
607|function rank(model: string): number {
