84|export function summarizeAdvice(results: (CaseResult & { advice?: CaseAdvice })[], provider: string, model: string): AdviceSummary {
85|  const advised = results.filter(r => r.advice && r.gate);
86|  let criteria = 0, supports = 0, partial = 0, silent = 0, doubts = 0, flagged = 0, cost = 0;
87|  for (const r of advised) {
88|    cost += r.advice!.costUsd;
89|    let doubted = false;
90|    for (const item of r.advice!.items) {
91|      criteria += 1;
92|      if (item.verdict === 'supports') supports += 1;
93|      else if (item.verdict === 'partial') partial += 1;
94|      else silent += 1;
95|      if (item.verdict !== 'supports' && r.gate!.criteria[item.criterion] === 'verified') { doubts += 1; doubted = true; }
96|    }
97|    if (doubted && r.outcome === 'false-pass') flagged += 1;
98|  }
99|  return {
100|    provider, model, cases: advised.length, criteria, supports, partial, silent,
101|    gateVerifiedAdvisorDoubts: doubts, falsePassesFlagged: flagged, falsePasses: results.filter(r => r.outcome === 'false-pass').length,
102|    costUsd: cost,
103|  };
