47|// The ledger's last row is 'pending' until the next commit fills its hash. The
48|// row belongs to the newest authored commit that has none of its own; a bot
49|// commit at HEAD is skipped, since it never carries a row.
50|export function resolvePending(event: Commit[], rows: Map<string, { date: string; text: string }>): Map<string, { date: string; text: string }> {
51|  const out = new Map(rows);
52|  const pending = out.get('pending');
53|  if (!pending) return out;
54|  const target = [...event].reverse().find(c => !c.bot);
55|  if (target && !out.has(target.hash)) { out.set(target.hash, pending); out.delete('pending'); }
56|  return out;
