1|// BUILD-LOG.md: one traceable log of the event build, generated from the
2|// sources of truth rather than written by hand: the git history since the
3|// `hackathon-start` tag, the ledger rows in NEW-WORK.md (matched by hash), the
4|// gate version at every commit that touched it, and the kept results files'
5|// own run headers (model, mode, gate version at the run, re-gates, advisor).
6|// Regenerate with `npm run log`; the file is committed so a reader can follow
7|// the build without a checkout.
8|import { execSync } from 'node:child_process';
9|import { existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
