36|  partial: number;
37|  silent: number;
38|  gateVerifiedAdvisorDoubts: number; // criteria the gate marked verified that the advisor called partial or silent
39|  falsePassesFlagged: number; // false-pass cases where the advisor doubted at least one criterion
40|  falsePasses: number;
41|  costUsd: number;
