44|export const ADVISOR_INSTRUCTIONS = `You are reviewing an appeal draft beside a physician. For each payer criterion you are given the exact quotes from the patient's chart that a drafting model cited as evidence for it.
45|
46|Judge, for each criterion, whether the quotes read literally satisfy it:
47|- supports: the quotes establish every element of the criterion.
48|- partial: the quotes address some elements and not others. Name the missing element.
49|- silent: the quotes do not address the criterion.
50|
51|Use only the quotes. Do not assume anything the quotes do not say. Do not add facts. Answer with one item per criterion, in the order given, each with one sentence of reasoning.`;
52|
53|export function buildAdvicePrompt(c: SyntheticCase, r: CaseResult): string {
54|  const gate = r.gate!;
55|  const lines: string[] = [];
56|  lines.push(`Denial: ${c.denial.text}`);
57|  lines.push('');
58|  for (const k of c.criteria) {
59|    lines.push(`${k.id}: ${k.text}`);
60|    const quotes = gate.evidence.filter(e => e.criterion === k.id && e.status === 'verified');
61|    if (quotes.length === 0) lines.push('  quotes: none cited');
62|    for (const q of quotes) lines.push(`  quote from ${q.citation}: "${q.quote}"`);
63|    lines.push('');
64|  }
65|  return lines.join('\n');
66|}
