68|export async function adviseCase(provider: Provider, c: SyntheticCase, r: CaseResult, effort: Effort): Promise<CaseAdvice> {
69|  if (!provider.ask) throw new Error(`${provider.label} cannot answer a structured question`);
70|  const base = { provider: provider.label, model: provider.model, effort };
71|  try {
72|    const a = await provider.ask({ system: [{ text: ADVISOR_INSTRUCTIONS, cache: true }], user: buildAdvicePrompt(c, r), schema: ADVICE_SCHEMA, effort, maxTokens: 2048 });
73|    const parsed = parseAdvice(a.rawText);
74|    if (!parsed.ok) return { ...base, model: a.model, latencyMs: a.latencyMs, costUsd: a.costUsd, items: [], error: parsed.error };
75|    const known = new Set(c.criteria.map(k => k.id));
76|    return { ...base, model: a.model, latencyMs: a.latencyMs, costUsd: a.costUsd, items: parsed.advice.items.filter(i => known.has(i.criterion)) };
77|  } catch (error: unknown) {
78|    const status = (error as { status?: number }).status;
79|    const kind = error instanceof Error ? error.constructor.name : 'Error';
80|    return { ...base, latencyMs: 0, costUsd: 0, items: [], error: `request failed: ${kind}${status ? ` (HTTP ${status})` : ''}` };
81|  }
82|}
