const kept=readdirSync(R).filter(f=>f.endsWith('.json')).sort().map(f=>({f,d:load(`${R}/${f}`)}));
console.log('KEPT files',kept.length);
for(const {f,d} of kept){
  const o=d.summary.outcomes; const agreed=(o['correct-pass']||0)+(o['correct-decline']||0);
  // fabricated sentence vs evidence
