  console.log(f.slice(0,55), `model=${d.run.model} agentic=${!!d.run.agentic} tools=${(d.run.tools||[]).join('/')} agreed=${agreed} outcomes=${JSON.stringify(o)} fabS=${fabS.size} fabE=${fabE.size} fabAll=${fabAll.size} sentVer=${d.summary.sentencesVerified} cost/case=${d.summary.costUsd.perCase.toFixed(4)} total=${d.summary.costUsd.total?.toFixed(2)} p50=${d.summary.latencyMs.p50} defended=${d.summary.stakesUsd?.defended} litmus=${(d.run.litmus||'').slice(0,30)} regated=${JSON.stringify(d.run.regated||[]).slice(0,120)} advice=${d.summary.advice?JSON.stringify({cases:d.summary.advice.cases,criteria:d.summary.advice.criteria,sup:d.summary.advice.supports,par:d.summary.advice.partial,sil:d.summary.advice.silent,cost:d.summary.advice.costUsd}):'-'}`);
}
for(const sub of ['repeats','payer','repair','effort','mutations']){
  try{ const files=readdirSync(`${R}/${sub}`).filter(f=>f.endsWith('.json')); console.log('\n',sub, files);
    for(const f of files){ if(sub==='mutations'){ const d=load(`${R}/${sub}/${f}`); console.log(f, 'gate=',d.gate?.slice(0,60),'corpus=',JSON.stringify(d.corpus),'byClass=',JSON.stringify(d.summary?.byClass)); continue;}
      const d=load(`${R}/${sub}/${f}`); const o=d.summary?.outcomes; console.log(f.slice(0,60), JSON.stringify(o), 'cases=',d.run?.cases,'model=',d.run?.model,'effort=',d.run?.effort); }
  }catch(e){ console.log(sub,'ERR',e.message)}
}
try{ const d=load(`${R}/intake/${readdirSync(R+'/intake')[0]}`); console.log('\nINTAKE', JSON.stringify(d.summary).slice(0,300)); const fields={}; for(const r of d.results){ for(const [k,v] of Object.entries(r.fields||{})){ fields[k]=fields[k]||{c:0,t:0,err:[]}; fields[k].t++; if(v.correct)fields[k].c++; else fields[k].err.push(`${r.caseId}:${JSON.stringify(v.got)}!=${JSON.stringify(v.expected)}`);} } console.log(JSON.stringify(fields,null,1)); }catch(e){console.log('intake err',e.message)}
// cases
const cases=readdirSync('build/synthetic/cases').filter(f=>f.endsWith('.json')).map(f=>load(`build/synthetic/cases/${f}`));
console.log('\nCASES',cases.length,'warranted',cases.filter(c=>c.expected.warranted).length,'subtypes',JSON.stringify(cases.reduce((a,c)=>{const k=c.expected.warranted?'warranted':c.expected.subtype||'?';a[k]=(a[k]||0)+1;return a;},{})));
console.log('stakes total',cases.reduce((a,c)=>a+c.stakesUsd,0),'warranted stakes',cases.filter(c=>c.expected.warranted).reduce((a,c)=>a+c.stakesUsd,0),'entries min/max/mean',Math.min(...cases.map(c=>c.chart.length)),Math.max(...cases.map(c=>c.chart.length)),(cases.reduce((a,c)=>a+c.chart.length,0)/cases.length).toFixed(2));
console.log('services/categories', new Set(cases.map(c=>c.category)).size, [...new Set(cases.map(c=>c.category))].join(','));
console.log('CARC', JSON.stringify(cases.reduce((a,c)=>{a[c.denial.carc]=(a[c.denial.carc]||0)+1;return a;},{})));
const unrelated=cases.map(c=>{const sup=new Set(Object.values(c.expected.support).flat()); return c.chart.filter(e=>!sup.has(e.id)).length/c.chart.length;});
console.log('unrelated entry fraction mean',(unrelated.reduce((a,b)=>a+b,0)/unrelated.length).toFixed(3));
const c23=cases.find(c=>c.id==='case-023'); console.log('case-023 expected',JSON.stringify(c23.expected));
// stored result expected for case-023 in kept open run
for(const {f,d} of kept){ const r=d.results.find(r=>r.caseId==='case-023'); if(r) console.log('kept case023',f.slice(0,40), r.outcome, JSON.stringify(r.expected), r.gate?.verdict); }
