for(const f of readdirSync('build/results/repair')){ const d=load(`build/results/repair/${f}`); const res=d.results; const offered=res.filter(r=>(r.repairs||[]).length>0); console.log('repair',d.run.model, 'blockedBefore',res.filter(r=>r.firstOutcome==='blocked').length,'offered',offered.length, offered.map(r=>`${r.caseId}:${r.firstOutcome}->${r.outcome}:${r.gate?.verdict}`).join(' '), 'summaryRepair', JSON.stringify(d.summary.repair)); }
