1|// Builds the static viewer: copies every results file and the synthetic
2|// cases into viewer/data/, writes the manifest the page reads, and bundles
3|// viewer/src/main.ts into one app.js. No server, no framework. viewer/data
4|// and viewer/app.js are build output and are not committed.
5|import { build } from 'esbuild';
6|import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
7|import { join, dirname } from 'node:path';
8|import { fileURLToPath } from 'node:url';
9|import { paperIndex } from '../viewer/src/figures.js';
10|
11|const here = dirname(fileURLToPath(import.meta.url));
12|const root = join(here, '..');
13|const viewer = join(root, 'viewer');
14|const data = join(viewer, 'data');
15|
16|rmSync(data, { recursive: true, force: true });
17|mkdirSync(join(data, 'results'), { recursive: true });
18|
19|// The kept physician-side runs (results/, group kept: Table 1, the scoreboard,
20|// the compare tab), then the post hoc directories the page lists last in the
21|// picker, labeled, and keeps off the scoreboard: the payer-side runs of Table 4
22|// (results/payer/), the repair-turn runs of Table 5 (results/repair/), and the
23|// effort sweep of Table 6 (results/effort/). Repeat runs (results/repeats/) and
24|// the intake run (results/intake/) are not shown.
25|const resultsDir = join(root, 'results');
26|type Group = 'kept' | 'payer' | 'repair' | 'effort';
27|const sub = (name: Group): { dir: string; f: string; group: Group }[] => {
28|  const dir = name === 'kept' ? resultsDir : join(resultsDir, name);
29|  return existsSync(dir) ? readdirSync(dir).filter(f => f.endsWith('.json')).sort().map(f => ({ dir, f, group: name })) : [];
30|};
31|const listed = [...sub('kept'), ...sub('payer'), ...sub('repair'), ...sub('effort')];
32|const results = listed.map(({ dir, f, group }) => {
