2|// litmus-gate: the LITMUS gate on the command line and as an MCP server.
3|//
4|//   litmus-gate check <draft.json> <case.json> [--json]   exit 0 pass, 1 blocked, 2 declined
5|//   litmus-gate mcp                                        serve the tools over stdio
6|//   litmus-gate contract                                   print the draft schema and the rules
7|import { readFileSync } from 'node:fs';
