91|export function renderMarkdown(r: GateResult): string {
92|  const lines: string[] = [];
93|  lines.push(`# LITMUS gate: ${r.verdict.toUpperCase()}`);
94|  lines.push(`${r.litmus.split(':')[0]?.trim() ?? r.litmus} · input hash ${r.inputHash.slice(0, 16)}…${r.errored ? ' · a check threw (error, not a pass)' : ''}`);
95|  if (r.declinedReason) lines.push(`Declined: ${r.declinedReason}`);
96|  if (r.reasons.length) { lines.push('', '## Why it is blocked'); for (const x of r.reasons) lines.push(`- ${x}`); }
97|  lines.push('', `## Sentences (${r.counts.verified} verified of ${r.counts.sentences})`);
98|  if (r.sentences.length === 0) lines.push('(none)');
99|  for (const s of r.sentences) {
