101|    lines.push(`${s.index + 1}. [${s.status}] ${s.text} (cites ${s.citation})${extra}`);
102|  }
103|  lines.push('', `## Evidence (${r.counts.evidenceVerified} verified of ${r.counts.evidence})`);
104|  if (r.evidence.length === 0) lines.push('(none)');
105|  for (const e of r.evidence) lines.push(`- [${e.status}] ${e.criterion} ← ${e.citation}: “${e.quote}”${e.status === 'verified' ? '' : ` — ${e.reason}`}`);
