107|  if (crit.length) { lines.push('', '## Criteria'); for (const [id, st] of crit) lines.push(`- ${id}: ${st}`); }
108|  lines.push('', 'The gate verifies that each statement is in the record. It does not verify that the record satisfies the criterion; a physician reads and signs.');
109|  return lines.join('\n');
