1|#!/usr/bin/env node
2|// litmus-gate: the LITMUS gate on the command line and as an MCP server.
3|//
4|//   litmus-gate check <draft.json> <case.json> [--json]   exit 0 pass, 1 blocked, 2 declined
5|//   litmus-gate mcp                                        serve the tools over stdio
6|//   litmus-gate contract                                   print the draft schema and the rules
7|import { readFileSync } from 'node:fs';
8|import { serveStdio } from '@modelcontextprotocol/server/stdio';
9|import { renderMarkdown, toJson, verifyDraft } from './lib.js';
10|import { contract, createServer, SERVER_NAME, SERVER_VERSION } from './server.js';
11|
12|const USAGE = `${SERVER_NAME} ${SERVER_VERSION}
13|usage:
14|  litmus-gate check <draft.json> <case.json> [--json]   verify a draft against the record; exit 0 pass, 1 blocked, 2 declined
15|  litmus-gate mcp                                        serve litmus_verify_draft, litmus_check_sentence, litmus_contract over stdio
16|  litmus-gate contract                                   print the draft schema, the admissible sources, and the rules
17|The gate verifies that each statement is in the record, not that the record satisfies the criterion.`;
18|
19|const EXIT = { pass: 0, blocked: 1, declined: 2 } as const;
20|
21|function readJson(path: string): unknown {
22|  try { return JSON.parse(readFileSync(path, 'utf8')); } catch (e) { throw new Error(`${path}: ${e instanceof Error ? e.message : String(e)}`); }
23|}
24|
25|function main(argv: string[]): number {
26|  const [cmd, ...rest] = argv;
27|  if (cmd === 'mcp') {
28|    serveStdio(createServer);
29|    console.error(`${SERVER_NAME} ${SERVER_VERSION} on stdio (gate ${contract().litmus.split(':')[0]})`);
30|    return -1; // keep the process alive for the transport
31|  }
32|  if (cmd === 'contract') { process.stdout.write(JSON.stringify(contract(), null, 2) + '\n'); return 0; }
33|  if (cmd === 'check') {
34|    const json = rest.includes('--json');
35|    const files = rest.filter(a => !a.startsWith('--'));
36|    if (files.length !== 2) { console.error(USAGE); return 64; }
37|    const [draftPath, casePath] = files as [string, string];
38|    const out = verifyDraft(readJson(casePath), readJson(draftPath));
39|    if (!out.ok) { console.error(out.error); return 65; }
40|    process.stdout.write((json ? toJson(out.result) : renderMarkdown(out.result)) + '\n');
41|    return EXIT[out.result.verdict];
42|  }
43|  console.error(USAGE);
44|  return 64;
45|}
46|
47|try {
48|  const code = main(process.argv.slice(2));
49|  if (code >= 0) process.exit(code);
50|} catch (e) {
51|  console.error(e instanceof Error ? e.message : String(e));
52|  process.exit(70);
