1|// The MCP server: three read-only tools and one resource over the gate. A
2|// fresh McpServer per connection, as the SDK's factory contract asks.
3|import { McpServer } from '@modelcontextprotocol/server';
4|import * as z from 'zod/v4';
5|import { APPEAL_SCHEMA, LITMUS_VERSION, draftInputSchema, renderMarkdown, renderSentenceMarkdown, sourcesInputSchema, toJson, verifyDraft, verifySentence } from './lib.js';
6|
7|export const SERVER_NAME = 'litmus-gate';
8|export const SERVER_VERSION = '0.1.0';
9|
10|const responseFormat = z.enum(['markdown', 'json']).default('markdown').describe("'markdown' for a readable report, 'json' for the full gate record as structured content");
11|
12|const sentenceInput = z.object({
13|  text: z.string().min(1).describe('one sentence of the draft, in the author\'s words'),
14|  citation: z.string().min(1).describe('the id of the single chart entry the sentence rests on, e.g. note-012'),
15|  quote: z.string().min(1).describe('at least two words copied exactly from that entry'),
16|});
17|
18|const RULES = [
19|  'Each sentence cites one chart entry and carries a verbatim quote from it; the quote must appear in that entry with only whitespace, case, and quote glyphs normalized.',
20|  'Every hard token in the sentence (number, date, code, and a side, left or right) must appear in the cited entry, the criteria, the denial, or the stated case facts; otherwise the sentence is refuted and the token named.',
21|  'When every missing token lives in another entry of the same chart, the sentence is returned as needs-citation naming that entry; the draft is still blocked.',
22|  'A draft passes only when every sentence verifies and every criterion it claims has verified evidence. A check that throws is an error, never a pass.',
23|  'The gate verifies presence, not sufficiency: that the words are in the record, not that the record meets the criterion. A physician reads and signs.',
24|];
25|
26|export function contract(): { litmus: string; server: string; version: string; rules: string[]; appealSchema: typeof APPEAL_SCHEMA; sourcesShape: string } {
27|  return {
28|    litmus: LITMUS_VERSION,
29|    server: SERVER_NAME,
30|    version: SERVER_VERSION,
31|    rules: RULES,
32|    appealSchema: APPEAL_SCHEMA,
33|    sourcesShape: 'Either {chart: [{id, date?, kind?, text}], criteria: [{id, text}], denial: string[], facts?: string[]} or a case file {chart, criteria, denial: {carc, rarc?, text, dateOfService, serviceEnd?}, patient: {alias, age, sex}, procedure: {code, codeSystem, description}, payer: {name, planType}}.',
34|  };
35|}
36|
37|export function createServer(): McpServer {
38|  const server = new McpServer({ name: SERVER_NAME, version: SERVER_VERSION });
39|
40|  server.registerTool(
41|    'litmus_verify_draft',
42|    {
43|      title: 'Verify a draft against the record',
44|      description: `Run the LITMUS referential gate over a drafted appeal (or any cited draft) against the chart it cites. Deterministic, no model inside, fails closed.
45|
46|Returns the verdict (pass, blocked, or declined), each sentence's status (verified, refuted with the invented token named, needs-citation with the entry to add, unresolved for an unknown citation, error), each evidence item's status, which criteria have verified evidence, and a SHA-256 of the inputs for the provenance record.
47|
48|Use it before a draft is shown to anyone: a blocked draft names what to fix. Use litmus_check_sentence while editing one sentence, and litmus_contract for the draft schema. The gate verifies that each statement is in the record; it does not judge whether the record satisfies the criterion.`,
49|      inputSchema: z.strictObject({ sources: sourcesInputSchema, draft: draftInputSchema, response_format: responseFormat }),
50|      annotations: { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false },
51|    },
52|    async ({ sources, draft, response_format }) => {
53|      const out = verifyDraft(sources, draft);
54|      if (!out.ok) return { content: [{ type: 'text', text: out.error }], isError: true };
55|      if (response_format === 'json') return { content: [{ type: 'text', text: toJson(out.result) }], structuredContent: JSON.parse(toJson(out.result)) as Record<string, unknown> };
56|      return { content: [{ type: 'text', text: renderMarkdown(out.result) }] };
57|    },
58|  );
59|
60|  server.registerTool(
61|    'litmus_check_sentence',
62|    {
63|      title: 'Check one sentence',
64|      description: `Run the gate's sentence check on one sentence, its citation, and its quote, against the chart: the same check litmus_verify_draft applies to every sentence, for use while a sentence is being written or repaired. Returns the status and, when it fails, the reason, the tokens with no admissible source, and the entries that would source them.`,
65|      inputSchema: z.strictObject({ sources: sourcesInputSchema, sentence: sentenceInput, response_format: responseFormat }),
66|      annotations: { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false },
67|    },
68|    async ({ sources, sentence, response_format }) => {
69|      const record = verifySentence(sources, sentence);
70|      const json = JSON.parse(JSON.stringify(record)) as Record<string, unknown>;
71|      if (response_format === 'json') return { content: [{ type: 'text', text: JSON.stringify(json, null, 2) }], structuredContent: json };
72|      return { content: [{ type: 'text', text: renderSentenceMarkdown(record) }], structuredContent: json };
73|    },
74|  );
75|
76|  server.registerTool(
77|    'litmus_contract',
78|    {
79|      title: 'The draft contract and the gate rules',
80|      description: 'Returns the JSON Schema a draft must satisfy (warranted, reason, evidence, sentences, each sentence with one citation and a verbatim quote), the shape of the admissible sources, the gate rules in plain words, and the gate version string that is stamped into every verdict. Call it once before drafting.',
81|      inputSchema: z.strictObject({}),
82|      annotations: { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false },
83|    },
84|    async () => {
85|      const c = contract();
86|      return { content: [{ type: 'text', text: JSON.stringify(c, null, 2) }], structuredContent: JSON.parse(JSON.stringify(c)) as Record<string, unknown> };
87|    },
88|  );
89|
90|  server.registerResource(
91|    'litmus-contract',
92|    'litmus://contract',
93|    { title: 'LITMUS gate contract', description: 'The draft schema, the admissible sources, the rules, and the gate version', mimeType: 'application/json' },
94|    async uri => ({ contents: [{ uri: uri.href, mimeType: 'application/json', text: JSON.stringify(contract(), null, 2) }] }),
95|  );
96|
97|  return server;
98|}

