28|async function waitForServer(url: string): Promise<void> {
29|  for (let i = 0; i < 50; i++) {
30|    try { const r = await fetch(url); if (r.ok) return; } catch { /* not yet */ }
31|    await new Promise(r => setTimeout(r, 100));
32|  }
33|  throw new Error(`server did not answer at ${url}`);
