36|// Removes every `@media (max-width: 900px) { ... }` block, braces matched, so
37|// the stylesheet can be rendered as the desktop alone sees it.
38|export function stripNarrow(css: string): string {
39|  const open = '@media (max-width: 900px)';
40|  let out = css;
41|  for (let at = out.indexOf(open); at !== -1; at = out.indexOf(open)) {
42|    const brace = out.indexOf('{', at);
43|    let depth = 0, i = brace;
44|    for (; i < out.length; i++) {
45|      if (out[i] === '{') depth++;
46|      else if (out[i] === '}' && --depth === 0) break;
47|    }
48|    out = out.slice(0, at) + out.slice(i + 1);
49|  }
50|  return out;
51|}
