1|// Dictation: the physician's spoken words as a chart entry. Given an audio
2|// file, a case id, and an entry id, this transcribes the recording with Muse
3|// Voice Transcribe through the Meta Model API (POST /v1/asr/transcribe,
4|// multipart: a JSON settings part and the WAV; dev.meta.ai docs, speech to
5|// text, read Oct 31, 2026), writes the transcript as that entry's text into a
6|// copy of the case under build/synthetic/dictated/, and runs the primary
7|// configuration (muse-spark-1.3, agentic, live CHART, --verbose) on that one
8|// case. The entry is then the physician's spoken words, so every quote the
9|// gate verifies against it is a quote of speech. Nothing clinical is judged
10|// here; the transcript is text, and the gate holds the draft to it as it holds
11|// a draft to any entry. The recording is Jim's to make: this stops with a
12|// clear error naming the file it needs, and prints the command to run once
13|// the file exists.
14|import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
15|import { basename, join, dirname, resolve } from 'node:path';
16|import { fileURLToPath, pathToFileURL } from 'node:url';
17|import { parseArgs } from 'node:util';
18|import { loadCases, runCase, selectProvider, summarize, resultFileName } from './harness.js';
19|import { POLICY_STATUS_TOOL, policyStatusExecutor } from './chart.js';
20|import { LITMUS_VERSION } from './litmus.js';
21|import type { SyntheticCase } from './synthetic/types.js';
22|
23|export const TRANSCRIBE_URL = 'https://api.meta.ai/v1/asr/transcribe';
24|export const TRANSCRIBE_MODEL = 'muse-voice-transcribe-1.0';
25|export const DEFAULT_AUDIO = 'assets/audio/case-001-note-013.wav';
26|
27|// --- the WAV the endpoint accepts: RIFF/WAVE, mono, 16-bit PCM, 16 or 24 kHz, at most 10 minutes
28|export type WavInfo = { ok: true; channels: number; sampleRate: number; bits: number; durationMs: number } | { ok: false; reason: string };
29|
30|export function wavInfo(b: Buffer): WavInfo {
31|  if (b.length < 44 || b.toString('ascii', 0, 4) !== 'RIFF' || b.toString('ascii', 8, 12) !== 'WAVE') return { ok: false, reason: 'not a RIFF/WAVE file' };
32|  // Walk the chunks for fmt and data.
33|  let at = 12;
34|  let fmt: { channels: number; sampleRate: number; bits: number; format: number } | null = null;
35|  let dataBytes = 0;
36|  while (at + 8 <= b.length) {
37|    const id = b.toString('ascii', at, at + 4);
38|    const size = b.readUInt32LE(at + 4);
39|    if (id === 'fmt ' && at + 24 <= b.length) fmt = { format: b.readUInt16LE(at + 8), channels: b.readUInt16LE(at + 10), sampleRate: b.readUInt32LE(at + 12), bits: b.readUInt16LE(at + 22) };
40|    if (id === 'data') { dataBytes = Math.min(size, b.length - at - 8); break; }
41|    at += 8 + size + (size % 2);
42|  }
43|  if (!fmt) return { ok: false, reason: 'no fmt chunk in the WAV' };
44|  const problems: string[] = [];
45|  if (fmt.format !== 1) problems.push('must be integer PCM');
46|  if (fmt.channels !== 1) problems.push('must be mono');
47|  if (fmt.bits !== 16) problems.push('must be 16-bit');
48|  if (fmt.sampleRate !== 16000 && fmt.sampleRate !== 24000) problems.push('must be 16 kHz or 24 kHz');
49|  const durationMs = fmt.sampleRate > 0 ? Math.round((dataBytes / (fmt.channels * (fmt.bits / 8))) / fmt.sampleRate * 1000) : 0;
50|  if (durationMs > 10 * 60 * 1000) problems.push('must be 10 minutes or less');
51|  if (problems.length) return { ok: false, reason: `the WAV ${problems.join(', ')} (ffmpeg -i in.wav -ac 1 -ar 24000 -c:a pcm_s16le out.wav)` };
52|  return { ok: true, channels: fmt.channels, sampleRate: fmt.sampleRate, bits: fmt.bits, durationMs };
53|}
54|
55|// --- the request, as the docs describe it: multipart with `request` (JSON) and `audio` (WAV)
56|export interface TranscribeSettings { model: string; mode: 'PUSH_TO_TALK' | 'ENDPOINTING'; audioEncoding: 'WAV'; languageBias: string[] }
57|
58|export function transcribeRequestParts(wav: Buffer, name: string): { url: string; settings: TranscribeSettings; form: FormData } {
59|  const settings: TranscribeSettings = { model: TRANSCRIBE_MODEL, mode: 'ENDPOINTING', audioEncoding: 'WAV', languageBias: ['English'] };
60|  const form = new FormData();
61|  form.set('request', new Blob([JSON.stringify(settings)], { type: 'application/json' }));
62|  form.set('audio', new Blob([new Uint8Array(wav)], { type: 'audio/wav' }), name);
63|  return { url: TRANSCRIBE_URL, settings, form };
