50|const CODE_SYSTEMS: Record<string, string> = { cpt: 'CPT', hcpcs: 'HCPCS', 'ms-drg': 'MS-DRG', msdrg: 'MS-DRG', drg: 'MS-DRG', cmg: 'CMG', hipps: 'HIPPS' };
