107|function readUsage(u: Record<string, unknown>): Usage {
108|  const n = (v: unknown): number => (typeof v === 'number' && Number.isFinite(v) ? v : 0);
109|  const details = (u['output_tokens_details'] ?? {}) as Record<string, unknown>;
110|  return { inputTokens: n(u['input_tokens']), cachedInputTokens: n(u['cache_read_input_tokens']), cacheWriteTokens: n(u['cache_creation_input_tokens']), outputTokens: n(u['output_tokens']), thinkingTokens: n(details['thinking_tokens']) };
