113|export async function readLetter(client: IntakeClient, c: SyntheticCase, png: Buffer, effort: Effort): Promise<IntakeCaseResult> {
114|  const anthropic = new Anthropic({ baseURL: client.baseURL, authToken: client.authToken, apiKey: null, maxRetries: 2, timeout: 180_000, ...(client.fetch ? { fetch: client.fetch } : {}) });
115|  const priceKey = client.priceKey ?? client.model;
116|  const started = Date.now();
117|  let response: Anthropic.Message;
118|  try {
119|    response = await anthropic.messages.create({
120|      model: client.model,
121|      max_tokens: 2048,
122|      system: [{ type: 'text', text: INTAKE_SYSTEM, cache_control: { type: 'ephemeral' } }],
123|      output_config: { effort, format: { type: 'json_schema', schema: INTAKE_SCHEMA } },
124|      messages: [{
125|        role: 'user',
126|        content: [
127|          { type: 'image', source: { type: 'base64', media_type: 'image/png', data: png.toString('base64') } },
128|          { type: 'text', text: INTAKE_PROMPT },
129|        ],
130|      }],
131|    });
132|  } catch (error: unknown) {
133|    const status = (error as { status?: number }).status;
134|    const kind = error instanceof Error ? error.constructor.name : 'Error';
135|    return { caseId: c.id, latencyMs: Date.now() - started, usage: { inputTokens: 0, cachedInputTokens: 0, cacheWriteTokens: 0, outputTokens: 0, thinkingTokens: 0 }, costUsd: 0, error: `request failed: ${kind}${status ? ` (HTTP ${status})` : ''}` };
136|  }
137|  const latencyMs = Date.now() - started;
138|  const usage = readUsage((response.usage ?? {}) as unknown as Record<string, unknown>);
139|  const cost = costUsd(priceKey, usage);
140|  const text = response.content.filter((b): b is Anthropic.TextBlock => b.type === 'text').map(b => b.text).join('');
141|  let got: unknown;
142|  try {
143|    got = JSON.parse(text);
144|  } catch {
145|    return { caseId: c.id, latencyMs, usage, costUsd: cost, stopReason: response.stop_reason, error: 'parse failed: answer is not valid JSON', rawPreview: text.slice(0, 200) };
146|  }
147|  return { caseId: c.id, latencyMs, usage, costUsd: cost, stopReason: response.stop_reason, got, fields: scoreFields(letterFields(c), got) };
148|}
