160|export function summarizeIntake(results: IntakeCaseResult[]): IntakeSummary {
161|  const fieldsCorrect: Record<string, number> = {};
162|  for (const r of results) for (const [f, s] of Object.entries(r.fields ?? {})) fieldsCorrect[f] = (fieldsCorrect[f] ?? 0) + (s.correct ? 1 : 0);
163|  const lat = results.filter(r => r.latencyMs > 0 && !r.error).map(r => r.latencyMs).sort((a, b) => a - b);
164|  const pct = (p: number): number => (lat.length ? lat[Math.max(0, Math.min(lat.length - 1, Math.ceil((p / 100) * lat.length) - 1))]! : 0);
165|  const total = results.reduce((n, r) => n + r.costUsd, 0);
166|  return {
167|    cases: results.length,
168|    fieldsCorrect,
169|    allCorrect: results.filter(r => r.fields && Object.values(r.fields).every(s => s.correct)).length,
170|    failed: results.filter(r => r.error).length,
171|    costUsd: { total, perCase: total / Math.max(1, results.length) },
172|    latencyMs: { mean: lat.length ? Math.round(lat.reduce((a, b) => a + b, 0) / lat.length) : 0, p50: pct(50), p95: pct(95) },
173|    tokens: { input: results.reduce((n, r) => n + r.usage.inputTokens + r.usage.cachedInputTokens + r.usage.cacheWriteTokens, 0), output: results.reduce((n, r) => n + r.usage.outputTokens, 0), thinking: results.reduce((n, r) => n + r.usage.thinkingTokens, 0) },
174|  };
