66|export interface Transcript { transcript: string; sessionId?: string; audioDurationMs?: number; turns?: { turnId?: number; startMs?: number; endMs?: number; transcript?: string; speaker?: string }[] }
67|
68|export async function transcribe(wav: Buffer, name: string, apiKey: string, doFetch: typeof fetch = fetch): Promise<Transcript> {
69|  const { url, form } = transcribeRequestParts(wav, name);
70|  const res = await doFetch(url, { method: 'POST', headers: { authorization: `Bearer ${apiKey}`, accept: 'application/json' }, body: form });
71|  if (!res.ok) throw new Error(`transcription returned HTTP ${res.status}${res.status === 400 ? ' (the audio is not a supported WAV, or is over 10 minutes)' : res.status === 429 ? ' (rate limited; retry later)' : ''}`);
72|  const body = (await res.json()) as Transcript;
73|  if (typeof body.transcript !== 'string') throw new Error('transcription answered without a transcript field');
74|  return body;
